        self.0 |= o.0;
    }
    pub fn remove(&mut self, o: Modifier) {
        self.0 &= !o.0;
    }
    pub fn minus(self, o: Modifier) -> Modifier {
        Modifier(self.0 & !o.0)
    }
    pub fn union(self, o: Modifier) -> Modifier {
        Modifier(self.0 | o.0)
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub struct Style {
    pub fg: Option<Color>,
    pub bg: Option<Color>,
    pub add_modifier: Modifier,
    pub sub_modifier: Modifier,
}

impl Style {
    pub fn new() -> Self {
        Self::default()
    }
    pub fn fg(mut self, c: Color) -> Self {
        self.fg = Some(c);
        self
    }
    pub fn bg(mut self, c: Color) -> Self {
        self.bg = Some(c);
        self
    }
    pub fn add_modifier(mut self, m: Modifier) -> Self {
        self.sub_modifier.remove(m);
        self.add_modifier.insert(m);
        self
    }
    pub fn patch(self, other: Style) -> Style {
        Style {
            fg: other.fg.or(self.fg),
            bg: other.bg.or(self.bg),
            add_modifier: self.add_modifier.minus(other.sub_modifier).union(other.add_modifier),
            sub_modifier: self.sub_modifier.minus(other.add_modifier).union(other.sub_modifier),
        }
    }
}

#[derive(Clone, PartialEq, Eq, Debug)]
pub struct Cell {
    pub symbol: String,
    pub fg: Color,
    pub bg: Color,
    pub modifier: Modifier,
    pub skip: bool,
}

impl Default for Cell {
    fn default() -> Self {
        Cell { symbol: " ".to_string(), fg: Color::Reset, bg: Color::Reset, modifier: Modifier::EMPTY, skip: false }
    }
}

impl Cell {
    pub fn set_symbol(&mut self, s: &str) -> &mut Self {
        self.symbol.clear();
        self.symbol.push_str(s);
        self
    }
    pub fn append_symbol(&mut self, s: &str) -> &mut Self {
        self.symbol.push_str(s);
        self
    }
    pub fn set_style(&mut self, style: Style) -> &mut Self {
        if let Some(c) = style.fg {
            self.fg = c;
        }
        if let Some(c) = style.bg {
            self.bg = c;
        }
        self.modifier.insert(style.add_modifier);
        self.modifier.remove(style.sub_modifier);
        self
    }
    pub fn reset(&mut self) {
        self.symbol.clear();
        self.symbol.push(' ');
        self.fg = Color::Reset;
        self.bg = Color::Reset;
        self.modifier = Modifier::EMPTY;
        self.skip = false;
    }
}

#[derive(Clone, Debug)]
pub struct Buffer {
    pub area: Rect,
    pub content: Vec<Cell>,
}

impl Buffer {
    pub fn empty(area: Rect) -> Self {
        let n = area.width as usize * area.height as usize;
        Buffer { area, content: vec![Cell::default(); n] }
    }

    pub fn index_of(&self, x: u16, y: u16) -> usize {
        (y - self.area.y) as usize * self.area.width as usize + (x - self.area.x) as usize
    }

    pub fn pos_of(&self, i: usize) -> (u16, u16) {
        let w = self.area.width as usize;
        (self.area.x + (i % w) as u16, self.area.y + (i / w) as u16)
    }

    pub fn get_mut(&mut self, x: u16, y: u16) -> &mut Cell {
        let i = self.index_of(x, y);
        &mut self.content[i]
    }

    pub fn in_bounds(&self, x: u16, y: u16) -> bool {
        x >= self.area.x && x < self.area.x + self.area.width && y >= self.area.y && y < self.area.y + self.area.height
    }

    pub fn reset(&mut self) {
        for c in self.content.iter_mut() {
            c.reset();
        }
    }

    pub fn resize(&mut self, area: Rect) {
        let n = area.width as usize * area.height as usize;
        if self.content.len() > n {
            self.content.truncate(n);
        } else {
            self.content.resize(n, Cell::default());
        }
        self.area = area;
    }

    pub fn set_style(&mut self, area: Rect, style: Style) {
        let area = area.intersection(self.area);
        for y in area.top()..area.bottom() {
            for x in area.left()..area.right() {
                self.get_mut(x, y).set_style(style);
            }
        }
    }

    /// Writes a string (skipping zero-width graphemes), returns the end position.
    pub fn set_stringn(&mut self, x: u16, y: u16, s: &str, width: usize, style: Style) -> (u16, u16) {
        if !self.in_bounds(x, y) {
            return (x, y);
        }
        let mut index = self.index_of(x, y);
        let mut x_offset = x as usize;
        let max_offset = std::cmp::min(self.area.right() as usize, width.saturating_add(x as usize));
        for g in UnicodeSegmentation::graphemes(s, true) {
            let w = str_width(g);
            if w == 0 {
                continue;
            }
            if w > max_offset.saturating_sub(x_offset) {
                break;
            }
            self.content[index].set_symbol(g);
            self.content[index].set_style(style);
            for i in index + 1..index + w {
                self.content[i].reset();
            }
            index += w;
            x_offset += w;
        }
        (x_offset as u16, y)
    }

    pub fn diff<'a>(&self, other: &'a Buffer) -> Vec<(u16, u16, &'a Cell)> {
        let prev = &self.content;
        let next = &other.content;
        let mut updates = vec![];
        let mut invalidated: usize = 0;
        let mut to_skip: usize = 0;
        for (i, (current, previous)) in next.iter().zip(prev.iter()).enumerate() {
            if !current.skip && (current != previous || invalidated > 0) && to_skip == 0 {
                let (x, y) = other.pos_of(i);
                updates.push((x, y, &next[i]));
            }
            let cw = str_width(&current.symbol);
            let pw = str_width(&previous.symbol);
            to_skip = cw.saturating_sub(1);
            let affected = std::cmp::max(cw, pw);
            invalidated = std::cmp::max(affected, invalidated).saturating_sub(1);
        }
        updates
    }
}

fn queue_modifier_diff<W: Write>(w: &mut W, from: Modifier, to: Modifier) -> io::Result<()> {
    let removed = from.minus(to);
    if removed.contains(Modifier::REVERSED) {
        queue!(w, SetAttribute(CAttribute::NoReverse))?;
    }
    if removed.contains(Modifier::BOLD) {
        queue!(w, SetAttribute(CAttribute::NormalIntensity))?;
        if to.contains(Modifier::DIM) {
            queue!(w, SetAttribute(CAttribute::Dim))?;
        }
    }
    if removed.contains(Modifier::ITALIC) {
        queue!(w, SetAttribute(CAttribute::NoItalic))?;
    }
    if removed.contains(Modifier::UNDERLINED) {
        queue!(w, SetAttribute(CAttribute::NoUnderline))?;
    }
    if removed.contains(Modifier::DIM) {
        queue!(w, SetAttribute(CAttribute::NormalIntensity))?;
    }
    if removed.contains(Modifier::CROSSED_OUT) {
        queue!(w, SetAttribute(CAttribute::NotCrossedOut))?;
    }
    if removed.contains(Modifier::SLOW_BLINK) || removed.contains(Modifier::RAPID_BLINK) {
        queue!(w, SetAttribute(CAttribute::NoBlink))?;
    }
    let added = to.minus(from);
    if added.contains(Modifier::REVERSED) {
        queue!(w, SetAttribute(CAttribute::Reverse))?;
    }
    if added.contains(Modifier::BOLD) {
        queue!(w, SetAttribute(CAttribute::Bold))?;
    }
    if added.contains(Modifier::ITALIC) {
        queue!(w, SetAttribute(CAttribute::Italic))?;
    }
    if added.contains(Modifier::UNDERLINED) {
        queue!(w, SetAttribute(CAttribute::Underlined))?;
    }
    if added.contains(Modifier::DIM) {
        queue!(w, SetAttribute(CAttribute::Dim))?;
    }
    if added.contains(Modifier::CROSSED_OUT) {
        queue!(w, SetAttribute(CAttribute::CrossedOut))?;
    }
    if added.contains(Modifier::SLOW_BLINK) {
        queue!(w, SetAttribute(CAttribute::SlowBlink))?;
    }
    if added.contains(Modifier::RAPID_BLINK) {
        queue!(w, SetAttribute(CAttribute::RapidBlink))?;
    }
    Ok(())
}

pub struct Terminal<W: Write> {
    writer: W,
    buffers: [Buffer; 2],
    current: usize,
    last_size: Rect,
}

pub struct Frame<'a> {
    pub buffer: &'a mut Buffer,
    pub area: Rect,
    pub cursor: Option<(u16, u16)>,
}

impl<W: Write> Terminal<W> {
    pub fn new(writer: W) -> io::Result<Self> {
        let size = Self::query_size();
        Ok(Terminal { writer, buffers: [Buffer::empty(size), Buffer::empty(size)], current: 0, last_size: size })
    }

    fn query_size() -> Rect {
        let (w, h) = crossterm::terminal::size().unwrap_or((80, 24));
        Rect::new(0, 0, w, h)
    }

    pub fn writer(&mut self) -> &mut W {
        &mut self.writer
    }

    pub fn clear(&mut self) -> io::Result<()> {
        queue!(self.writer, Clear(ClearType::All))?;
        self.writer.flush()?;
        self.buffers[1 - self.current].reset();
        Ok(())
    }

    pub fn resize(&mut self, area: Rect) -> io::Result<()> {
        self.buffers[self.current].resize(area);
        self.buffers[1 - self.current].resize(area);
        self.last_size = area;
        self.clear()
    }

    pub fn autoresize(&mut self) -> io::Result<()> {
        let size = Self::query_size();
        if size != self.last_size {
            self.resize(size)?;
        }
        Ok(())
    }

    pub fn draw<F: FnOnce(&mut Frame)>(&mut self, f: F) -> io::Result<()> {
        self.autoresize()?;
        let area = self.last_size;
        let cursor;
        {
            let buf = &mut self.buffers[self.current];
            let mut frame = Frame { buffer: buf, area, cursor: None };
            f(&mut frame);
            cursor = frame.cursor;
        }
        self.flush()?;
        match cursor {
            None => {
                queue!(self.writer, Hide)?;
            }
            Some((x, y)) => {
                queue!(self.writer, Show)?;
                queue!(self.writer, MoveTo(x, y))?;
            }
        }
        // swap buffers
        self.buffers[1 - self.current].reset();
        self.current = 1 - self.current;
        self.writer.flush()?;
        Ok(())
    }

    fn flush(&mut self) -> io::Result<()> {
        let prev = &self.buffers[1 - self.current];
        let cur = &self.buffers[self.current];
        let updates = prev.diff(cur);
        let w = &mut self.writer;
        let mut fg = Color::Reset;
        let mut bg = Color::Reset;
        let mut modifier = Modifier::EMPTY;
        let mut last_pos: Option<(u16, u16)> = None;
        for (x, y, cell) in updates {
            if !matches!(last_pos, Some(p) if x == p.0 + 1 && y == p.1) {
                queue!(w, MoveTo(x, y))?;
            }
            last_pos = Some((x, y));
            if cell.modifier != modifier {
                queue_modifier_diff(w, modifier, cell.modifier)?;
                modifier = cell.modifier;
            }
            if cell.fg != fg || cell.bg != bg {
                queue!(w, SetColors(Colors::new(cell.fg.to_crossterm(), cell.bg.to_crossterm())))?;
                fg = cell.fg;
                bg = cell.bg;
            }
            queue!(w, Print(&cell.symbol))?;
        }
        queue!(
            w,
            SetForegroundColor(CColor::Reset),
            SetBackgroundColor(CColor::Reset),
            SetAttribute(CAttribute::Reset)
        )?;
        Ok(())
    }
}
