//! Widgets mimicking the behaviour of the classic ratatui widgets.

use unicode_segmentation::UnicodeSegmentation;

use crate::tui::{str_width, Buffer, Rect, Style};

#[derive(Clone, Debug, Default)]
pub struct Span {
    pub content: String,
    pub style: Style,
}

impl Span {
    pub fn raw<S: Into<String>>(s: S) -> Self {
        Span { content: s.into(), style: Style::default() }
    }
    pub fn styled<S: Into<String>>(s: S, style: Style) -> Self {
        Span { content: s.into(), style }
    }
    pub fn width(&self) -> usize {
        str_width(&self.content)
    }

    fn graphemes(&self) -> impl Iterator<Item = &str> {
        self.content.graphemes(true).filter(|g| *g != "\n")
    }

    /// Render a span into an area (old ratatui semantics: zero-width graphemes are appended).
    pub fn render(&self, area: Rect, buf: &mut Buffer) {
        let area = area.intersection(buf.area);
        if area.width == 0 || area.height == 0 {
            // still behave like original: nothing rendered
            return;
        }
        let right = area.right();
        let y = area.y;
        let mut x = area.x;
        for (i, g) in self.graphemes().enumerate() {
            let w = str_width(g) as u16;
            let next_x = x.saturating_add(w);
            if next_x > right {
                break;
            }
            if i == 0 {
                buf.get_mut(x, y).set_symbol(g).set_style(self.style);
            } else if x == area.x {
                buf.get_mut(x, y).append_symbol(g).set_style(self.style);
            } else if w == 0 {
                buf.get_mut(x - 1, y).append_symbol(g).set_style(self.style);
            } else {
                buf.get_mut(x, y).set_symbol(g).set_style(self.style);
            }
            for xh in (x + 1)..next_x {
                buf.get_mut(xh, y).reset();
            }
            x = next_x;
        }
    }
}

#[derive(Clone, Debug, Default)]
pub struct Line {
    pub spans: Vec<Span>,
    pub style: Style,
}

impl Line {
    pub fn from_spans(spans: Vec<Span>) -> Self {
        Line { spans, style: Style::default() }
    }
    pub fn raw<S: Into<String>>(s: S) -> Self {
        Line { spans: vec![Span::raw(s)], style: Style::default() }
    }
    pub fn styled<S: Into<String>>(s: S, style: Style) -> Self {
        Line { spans: vec![Span::styled(s, style)], style: Style::default() }
    }
    pub fn width(&self) -> usize {
        self.spans.iter().map(|s| s.width()).sum()
    }

    /// Render line left aligned (old ratatui Line widget).
    pub fn render(&self, area: Rect, buf: &mut Buffer) {
        let area = area.intersection(buf.area);
        buf.set_style(area, self.style);
        if area.width == 0 || area.height == 0 {
            return;
        }
        let mut x = area.left();
        for span in &self.spans {
            let span_width = span.width() as u16;
            let span_area = Rect { x, y: area.y, width: span_width.min(area.right().saturating_sub(x)), height: 1 };
            span.render(span_area, buf);
            x = x.saturating_add(span_width);
            if x >= area.right() {
                break;
            }
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Alignment {
    Left,
    Center,
    Right,
}

pub struct Title {
    pub line: Line,
    pub alignment: Alignment,
}

pub struct Block {
    pub titles: Vec<Title>,
    pub border_style: Style,
    pub style: Style,
    pub borders: bool,
}

pub const TOP_LEFT: &str = "╭";
pub const TOP_RIGHT: &str = "╮";
pub const BOTTOM_LEFT: &str = "╰";
pub const BOTTOM_RIGHT: &str = "╯";
pub const VERTICAL: &str = "│";
pub const HORIZONTAL: &str = "─";

impl Block {
    pub fn bordered() -> Self {
        Block { titles: vec![], border_style: Style::default(), style: Style::default(), borders: true }
    }
    pub fn title(mut self, line: Line, alignment: Alignment) -> Self {
        self.titles.push(Title { line, alignment });
        self
    }
    pub fn border_style(mut self, s: Style) -> Self {
        self.border_style = s;
        self
    }
    #[allow(dead_code)]
    pub fn style(mut self, s: Style) -> Self {
        self.style = s;
        self
    }

    pub fn inner(&self, area: Rect) -> Rect {
        if !self.borders {
            return area;
        }
        let mut inner = area;
        inner.x = inner.x.saturating_add(1).min(inner.right());
        inner.width = inner.width.saturating_sub(1);
        inner.y = inner.y.saturating_add(1).min(inner.bottom());
        inner.height = inner.height.saturating_sub(1);
        inner.width = inner.width.saturating_sub(1);
        inner.height = inner.height.saturating_sub(1);
        inner
    }

    pub fn render(&self, area: Rect, buf: &mut Buffer) {
        let area = area.intersection(buf.area);
        if area.width == 0 || area.height == 0 {
            return;
        }
        buf.set_style(area, self.style);
        if self.borders {
            let bs = self.border_style;
            for y in area.top()..area.bottom() {
                buf.get_mut(area.left(), y).set_symbol(VERTICAL).set_style(bs);
            }
            for x in area.left()..area.right() {
                buf.get_mut(x, area.top()).set_symbol(HORIZONTAL).set_style(bs);
            }
            let xr = area.right() - 1;
            for y in area.top()..area.bottom() {
                buf.get_mut(xr, y).set_symbol(VERTICAL).set_style(bs);
            }
            let yb = area.bottom() - 1;
            for x in area.left()..area.right() {
                buf.get_mut(x, yb).set_symbol(HORIZONTAL).set_style(bs);
            }
            buf.get_mut(area.right() - 1, area.bottom() - 1).set_symbol(BOTTOM_RIGHT);
            buf.get_mut(area.right() - 1, area.top()).set_symbol(TOP_RIGHT);
            buf.get_mut(area.left(), area.bottom() - 1).set_symbol(BOTTOM_LEFT);
            buf.get_mut(area.left(), area.top()).set_symbol(TOP_LEFT);
        }
        self.render_titles(area, buf);
    }

    fn titles_area(&self, area: Rect) -> Rect {
        let b = if self.borders { 1 } else { 0 };
        Rect { x: area.left() + b, y: area.top(), width: area.width.saturating_sub(b).saturating_sub(b), height: 1 }
    }

    fn render_titles(&self, area: Rect, buf: &mut Buffer) {
        // right titles
        {
            let mut titles_area = self.titles_area(area);
            for t in self.titles.iter().filter(|t| t.alignment == Alignment::Right).rev() {
                if titles_area.width == 0 || titles_area.height == 0 {
                    break;
                }
                let tw = t.line.width() as u16;
                let ta = Rect {
                    x: titles_area.right().saturating_sub(tw).max(titles_area.left()),
                    width: tw.min(titles_area.width),
                    ..titles_area
                };
                t.line.render(ta, buf);
                titles_area.width = titles_area.width.saturating_sub(tw).saturating_sub(1);
            }
        }
        // center titles
        {
            let titles: Vec<&Title> = self.titles.iter().filter(|t| t.alignment == Alignment::Center).collect();
            let total: u16 = titles.iter().map(|t| t.line.width() as u16 + 1).sum::<u16>().saturating_sub(1);
            let ta0 = self.titles_area(area);
            let mut titles_area = Rect { x: ta0.left() + (ta0.width.saturating_sub(total) / 2), ..ta0 };
            for t in titles {
                if titles_area.width == 0 || titles_area.height == 0 {
                    break;
                }
                let tw = t.line.width() as u16;
                let ta = Rect { width: tw.min(titles_area.width), ..titles_area };
                t.line.render(ta, buf);
                titles_area.x = titles_area.x.saturating_add(tw + 1);
                titles_area.width = titles_area.width.saturating_sub(tw + 1);
            }
        }
        // left titles
        {
            let mut titles_area = self.titles_area(area);
            for t in self.titles.iter().filter(|t| t.alignment == Alignment::Left) {
                if titles_area.width == 0 || titles_area.height == 0 {
                    break;
                }
                let tw = t.line.width() as u16;
                let ta = Rect { width: tw.min(titles_area.width), ..titles_area };
                t.line.render(ta, buf);
                titles_area.x = titles_area.x.saturating_add(tw + 1);
                titles_area.width = titles_area.width.saturating_sub(tw + 1);
            }
        }
    }
}

pub fn render_clear(area: Rect, buf: &mut Buffer) {
    let area = area.intersection(buf.area);
    for y in area.top()..area.bottom() {
        for x in area.left()..area.right() {
            buf.get_mut(x, y).reset();
        }
    }
}

// ---------------------------------------------------------------- Paragraph

struct SG<'a> {
    symbol: &'a str,
    style: Style,
}

fn is_ws(s: &str) -> bool {
    const NBSP: &str = "\u{00a0}";
    const ZWSP: &str = "\u{200b}";
    s == ZWSP || (s.chars().all(char::is_whitespace) && s != NBSP)
}

fn word_wrap<'a>(line: Vec<SG<'a>>, max_width: u16, trim: bool, out: &mut Vec<Vec<SG<'a>>>) {
    let mut wrapped: Vec<Vec<SG<'a>>> = vec![];
    let mut pending_line: Vec<SG<'a>> = vec![];
    let mut pending_word: Vec<SG<'a>> = vec![];
    let mut pending_ws: std::collections::VecDeque<SG<'a>> = std::collections::VecDeque::new();
    let mut line_width: u16 = 0;
    let mut word_width: u16 = 0;
    let mut ws_width: u16 = 0;
    let mut non_ws_prev = false;

    for g in line {
        let is_whitespace = is_ws(g.symbol);
        let symbol_width = str_width(g.symbol) as u16;
        if symbol_width > max_width {
            continue;
        }
        let word_found = non_ws_prev && is_whitespace;
        let trimmed_overflow = pending_line.is_empty() && trim && word_width + symbol_width > max_width;
        let whitespace_overflow = pending_line.is_empty() && trim && ws_width + symbol_width > max_width;
        let untrimmed_overflow =
            pending_line.is_empty() && !trim && word_width + ws_width + symbol_width > max_width;
        if word_found || trimmed_overflow || whitespace_overflow || untrimmed_overflow {
            if !pending_line.is_empty() || !trim {
                pending_line.extend(pending_ws.drain(..));
                line_width += ws_width;
            }
            pending_line.append(&mut pending_word);
            line_width += word_width;
            pending_ws.clear();
            ws_width = 0;
            word_width = 0;
        }
        let line_full = line_width >= max_width;
        let pending_word_overflow = symbol_width > 0 && line_width + ws_width + word_width >= max_width;
        if line_full || pending_word_overflow {
            let mut remaining_width = max_width.saturating_sub(line_width);
            wrapped.push(std::mem::take(&mut pending_line));
            line_width = 0;
            while let Some(gr) = pending_ws.front() {
                let w = str_width(gr.symbol) as u16;
                if w > remaining_width {
                    break;
                }
                ws_width -= w;
                remaining_width -= w;
                pending_ws.pop_front();
            }
            if is_whitespace && pending_ws.is_empty() {
                continue;
            }
        }
        if is_whitespace {
            ws_width += symbol_width;
            pending_ws.push_back(g);
        } else {
            word_width += symbol_width;
            pending_word.push(g);
        }
        non_ws_prev = !is_whitespace;
    }
    if pending_line.is_empty() && pending_word.is_empty() && !pending_ws.is_empty() {
        wrapped.push(vec![]);
    }
    if !pending_line.is_empty() || !trim {
        pending_line.extend(pending_ws.drain(..));
    }
    pending_line.append(&mut pending_word);
    if !pending_line.is_empty() {
        wrapped.push(pending_line);
    }
    if wrapped.is_empty() {
        wrapped.push(vec![]);
    }
    out.extend(wrapped);
}

pub struct Paragraph {
    pub lines: Vec<(Line, Option<Alignment>)>,
    pub style: Style,
    pub alignment: Alignment,
    pub wrap: Option<bool>,
    pub scroll_x: u16,
    pub block: Option<Block>,
}

impl Paragraph {
    pub fn new(lines: Vec<Line>) -> Self {
        Paragraph {
            lines: lines.into_iter().map(|l| (l, None)).collect(),
            style: Style::default(),
            alignment: Alignment::Left,
            wrap: None,
            scroll_x: 0,
            block: None,
        }
    }
    pub fn style(mut self, s: Style) -> Self {
        self.style = s;
        self
    }
    pub fn alignment(mut self, a: Alignment) -> Self {
        self.alignment = a;
        self
    }
    pub fn wrap(mut self, trim: bool) -> Self {
        self.wrap = Some(trim);
        self
    }
    pub fn scroll_x(mut self, x: u16) -> Self {
        self.scroll_x = x;
        self
    }
    pub fn block(mut self, b: Block) -> Self {
        self.block = Some(b);
        self
    }

    pub fn render(&self, area: Rect, buf: &mut Buffer) {
        let area = area.intersection(buf.area);
        buf.set_style(area, self.style);
        let text_area = match &self.block {
            Some(b) => {
                b.render(area, buf);
                b.inner(area)
            }
            None => area,
        };
        if text_area.width == 0 || text_area.height == 0 {
            return;
        }
        let base = self.style;
        let mut rows: Vec<(Vec<SG>, Alignment)> = vec![];
        for (line, al) in &self.lines {
            let alignment = al.unwrap_or(self.alignment);
            let lstyle = base.patch(line.style);
            let mut graphemes: Vec<SG> = vec![];
            for span in &line.spans {
                let st = lstyle.patch(span.style);
                for g in span.graphemes() {
                    graphemes.push(SG { symbol: g, style: st });
                }
            }
            match self.wrap {
                Some(trim) => {
                    let mut out = vec![];
                    word_wrap(graphemes, text_area.width, trim, &mut out);
                    for l in out {
                        rows.push((l, alignment));
                    }
                }
                None => {
                    // truncate with horizontal offset
                    let mut cur: Vec<SG> = vec![];
                    let mut width: u16 = 0;
                    let mut hoff = self.scroll_x as usize;
                    for g in graphemes {
                        let w = str_width(g.symbol) as u16;
                        if w > text_area.width {
                            continue;
                        }
                        if width + w > text_area.width {
                            break;
                        }
                        let sym = if hoff == 0 || alignment != Alignment::Left {
                            g.symbol
                        } else {
                            let w = str_width(g.symbol);
                            if w > hoff {
                                hoff = 0;
                                g.symbol
                            } else {
                                hoff -= w;
                                ""
                            }
                        };
                        width += str_width(sym) as u16;
                        cur.push(SG { symbol: sym, style: g.style });
                    }
                    rows.push((cur, alignment));
                }
            }
            if rows.len() >= text_area.height as usize && self.wrap.is_none() {
                break;
            }
        }
        for (y, (row, alignment)) in rows.iter().enumerate() {
            if y >= text_area.height as usize {
                break;
            }
            let lw: u16 = row.iter().map(|g| str_width(g.symbol) as u16).sum();
            let mut x = match alignment {
                Alignment::Center => (text_area.width / 2).saturating_sub(lw / 2),
                Alignment::Right => text_area.width.saturating_sub(lw),
                Alignment::Left => 0,
            };
            for g in row {
                let w = str_width(g.symbol) as u16;
                if w == 0 {
                    continue;
                }
                let sym = if g.symbol.is_empty() { " " } else { g.symbol };
                buf.get_mut(text_area.left() + x, text_area.top() + y as u16).set_symbol(sym).set_style(g.style);
                x += w;
            }
        }
    }
}

// ---------------------------------------------------------------- List

pub struct List {
    pub items: Vec<Line>,
    pub style: Style,
    pub highlight_style: Style,
    pub highlight_symbol: Option<String>,
    pub block: Option<Block>,
}

#[derive(Clone, Debug, Default)]
pub struct ListState {
    pub offset: usize,
    pub selected: Option<usize>,
}

impl List {
    pub fn new(items: Vec<Line>) -> Self {
        List { items, style: Style::default(), highlight_style: Style::default(), highlight_symbol: None, block: None }
    }
    pub fn style(mut self, s: Style) -> Self {
        self.style = s;
        self
    }
    pub fn highlight_style(mut self, s: Style) -> Self {
        self.highlight_style = s;
        self
    }
    pub fn highlight_symbol(mut self, s: &str) -> Self {
        self.highlight_symbol = Some(s.to_string());
        self
    }
    pub fn block(mut self, b: Block) -> Self {
        self.block = Some(b);
        self
    }

    fn get_items_bounds(&self, selected: Option<usize>, offset: usize, max_height: usize) -> (usize, usize) {
        let offset = offset.min(self.items.len().saturating_sub(1));
        let mut first = offset;
        let mut last = offset;
        let mut height = 0usize;
        for _ in self.items.iter().skip(offset) {
            if height + 1 > max_height {
                break;
            }
            height += 1;
            last += 1;
        }
        let index_to_display = selected.unwrap_or(offset);
        while index_to_display >= last {
            height = height.saturating_add(1);
            last += 1;
            while height > max_height {
                height = height.saturating_sub(1);
                first += 1;
            }
        }
        while index_to_display < first {
            first -= 1;
            height = height.saturating_add(1);
            while height > max_height {
                last -= 1;
                height = height.saturating_sub(1);
            }
        }
        (first, last)
    }

    pub fn render(&self, area: Rect, buf: &mut Buffer, state: &mut ListState) {
        let area = area.intersection(buf.area);
        buf.set_style(area, self.style);
        let list_area = match &self.block {
            Some(b) => {
                b.render(area, buf);
                b.inner(area)
            }
            None => area,
        };
        if list_area.width == 0 || list_area.height == 0 || self.items.is_empty() {
            return;
        }
        if let Some(s) = state.selected {
            if s >= self.items.len() {
                state.selected = Some(self.items.len().saturating_sub(1));
            }
        }
        let list_height = list_area.height as usize;
        let (start, end) = self.get_items_bounds(state.selected, state.offset, list_height);
        state.offset = start;
        let hsym = self.highlight_symbol.clone().unwrap_or_default();
        let hsym_w = str_width(&hsym) as u16;
        let blank: String = " ".repeat(hsym_w as usize);
        let selection_spacing = state.selected.is_some();
        let mut current_height = 0u16;
        for (i, item) in self.items.iter().enumerate().skip(state.offset).take(end - start) {
            let x = list_area.left();
            let y = list_area.top() + current_height;
            current_height += 1;
            let row_area = Rect { x, y, width: list_area.width, height: 1 };
            let item_style = self.style.patch(Style::default());
            buf.set_style(row_area, item_style);
            let is_selected = state.selected == Some(i);
            let item_area = if selection_spacing {
                Rect { x: row_area.x + hsym_w, width: row_area.width.saturating_sub(hsym_w), ..row_area }
            } else {
                row_area
            };
            item.render(item_area, buf);
            if selection_spacing {
                let sym = if is_selected { &hsym } else { &blank };
                buf.set_stringn(x, y, sym, list_area.width as usize, item_style);
            }
            if is_selected {
                buf.set_style(row_area, self.highlight_style);
            }
        }
    }
}
