                self.cursor += 1;
                true
            }
            DeletePrevChar => {
                if self.cursor == 0 {
                    false
                } else {
                    self.cursor -= 1;
                    self.value = self
                        .value
                        .chars()
                        .enumerate()
                        .filter(|(i, _)| *i != self.cursor)
                        .map(|(_, c)| c)
                        .collect();
