                    let remaining: Vec<char> = self.value.chars().skip(self.cursor).collect();
                    let rev: Vec<char> = self
                        .value
                        .chars()
                        .rev()
                        .skip(n.max(self.cursor) - self.cursor)
                        .skip_while(|c| !c.is_alphanumeric())
                        .skip_while(|c| c.is_alphanumeric())
