                }
            }
            DeleteNextWord => {
                if self.cursor == self.len() {
                    false
                } else {
                    self.value = self
                        .value
                        .chars()
                        .take(self.cursor)
                        .chain(
                            self.value
                                .chars()
                                .skip(self.cursor)
                                .skip_while(|c| c.is_alphanumeric())
                                .skip_while(|c| !c.is_alphanumeric()),
                        )
                        .collect();
                    true
                }
            }
            GoToStart => {
                self.cursor = 0;
                false
            }
            GoToEnd => {
                self.cursor = self.len();
                false
            }
            DeleteTillEnd => {
                let changed = self.cursor < self.len();
                self.value = self.value.chars().take(self.cursor).collect();
                changed
            }
        }
    }

    pub fn visual_cursor(&self) -> usize {
        if self.cursor == 0 {
            return 0;
        }
        let end = self.value.char_indices().nth(self.cursor).map_or(self.value.len(), |(i, _)| i);
        unicode_width::UnicodeWidthStr::width(&self.value[..end])
    }

    pub fn visual_scroll(&self, width: usize) -> usize {
        let scroll = self.visual_cursor().max(width) - width;
        let mut uscroll = 0;
        let mut chars = self.value.chars();
        while uscroll < scroll {
            match chars.next() {
                Some(c) => {
                    uscroll += unicode_width::UnicodeWidthChar::width(c).unwrap_or(0);
                }
                None => break,
            }
        }
        uscroll
    }
}
