//! Running ripgrep and parsing its JSON output.

use std::collections::VecDeque;
use std::process::{Command, Stdio};

#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub enum SearchMode {
    #[default]
    Simple,
    MatchCase,
    MatchWholeWord,
    MatchCaseWholeWord,
    Regex,
}

impl SearchMode {
    pub fn label(self) -> &'static str {
        match self {
            SearchMode::Simple => "Simple",
            SearchMode::MatchCase => "Match Case",
            SearchMode::MatchWholeWord => "Match Whole Word",
            SearchMode::MatchCaseWholeWord => "Match Case Whole Word",
            SearchMode::Regex => "Regex",
        }
    }
    pub fn next(self) -> Self {
        match self {
            SearchMode::Simple => SearchMode::MatchCase,
            SearchMode::MatchCase => SearchMode::MatchWholeWord,
            SearchMode::MatchWholeWord => SearchMode::MatchCaseWholeWord,
            SearchMode::MatchCaseWholeWord => SearchMode::Regex,
            SearchMode::Regex => SearchMode::Simple,
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub enum ReplaceMode {
    #[default]
    Simple,
    PreserveCase,
    DeleteLine,
}

impl ReplaceMode {
    pub fn label(self) -> &'static str {
        match self {
            ReplaceMode::Simple => "Simple",
            ReplaceMode::PreserveCase => "Preserve Case",
            ReplaceMode::DeleteLine => "Delete Line",
        }
    }
    pub fn next(self) -> Self {
        match self {
            ReplaceMode::Simple => ReplaceMode::PreserveCase,
            ReplaceMode::PreserveCase => ReplaceMode::DeleteLine,
            ReplaceMode::DeleteLine => ReplaceMode::Simple,
        }
    }
}

#[derive(Clone, Debug)]
pub struct SubMatch {
    pub start: usize,
    pub end: usize,
}

#[derive(Clone, Debug)]
pub struct Match {
    pub line_number: usize,
    pub text: String,
    pub submatches: Vec<SubMatch>,
    pub before: Vec<String>,
    pub after: Vec<String>,
}

#[derive(Clone, Debug)]
pub struct FileResult {
    /// Path as reported by ripgrep (used for file access).
    pub path: String,
    /// Path shown to the user.
    pub display: String,
    pub matches: Vec<Match>,
}

impl FileResult {
    pub fn total(&self) -> usize {
        self.matches.iter().map(|m| m.submatches.len()).sum()
    }
}

fn json_text(v: &serde_json::Value) -> Option<String> {
    if let Some(t) = v.get("text").and_then(|t| t.as_str()) {
        return Some(t.to_string());
    }
    if let Some(b) = v.get("bytes").and_then(|t| t.as_str()) {
        let bytes = base64_decode(b);
        return Some(String::from_utf8_lossy(&bytes).into_owned());
    }
    None
}

fn base64_decode(s: &str) -> Vec<u8> {
    let mut out = vec![];
    let mut buf = 0u32;
    let mut bits = 0;
    for c in s.bytes() {
        let v = match c {
            b'A'..=b'Z' => c - b'A',
            b'a'..=b'z' => c - b'a' + 26,
            b'0'..=b'9' => c - b'0' + 52,
            b'+' => 62,
            b'/' => 63,
            _ => continue,
        } as u32;
        buf = (buf << 6) | v;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            out.push((buf >> bits) as u8);
            buf &= (1 << bits) - 1;
        }
    }
    out
}

pub fn clean_line(s: &str) -> String {
    let s = s.strip_suffix('\n').unwrap_or(s);
    let s = s.strip_suffix('\r').unwrap_or(s);
    s.to_string()
}

pub fn display_path(path: &str, root: &str) -> String {
    let prefix = format!("{}/", root);
    match path.strip_prefix(&prefix) {
        Some(p) => p.to_string(),
        None => path.to_string(),
    }
}

pub fn run_search(text: &str, mode: SearchMode, root: &str) -> Vec<FileResult> {
    let mut args: Vec<String> = vec!["--json".into(), "-C".into(), "3".into()];
    match mode {
        SearchMode::Simple => {
            args.push("-F".into());
            args.push("-i".into());
        }
        SearchMode::MatchCase => {
            args.push("-s".into());
        }
        SearchMode::MatchWholeWord => {
            args.push("-w".into());
            args.push("-i".into());
        }
        SearchMode::MatchCaseWholeWord => {
            args.push("-w".into());
            args.push("-s".into());
        }
        SearchMode::Regex => {}
    }
    args.push(text.to_string());
    args.push(root.to_string());
    let output = Command::new("rg")
        .args(&args)
        .stdin(Stdio::null())
        .stderr(Stdio::null())
        .stdout(Stdio::piped())
        .output();
    let output = match output {
        Ok(o) => o,
        Err(_) => return vec![],
    };
    parse_output(&String::from_utf8_lossy(&output.stdout), root)
}

pub fn parse_output(out: &str, root: &str) -> Vec<FileResult> {
    let mut results: Vec<FileResult> = vec![];
