//! Replacement logic.

use regex::{NoExpand, Regex, RegexBuilder};

use crate::search::{FileResult, ReplaceMode, SearchMode};

pub fn build_regex(text: &str, mode: SearchMode) -> Option<Regex> {
    let escaped = regex::escape(text);
    let (pattern, ci) = match mode {
        SearchMode::Simple | SearchMode::Regex => (escaped, true),
        SearchMode::MatchCase => (escaped, false),
        SearchMode::MatchWholeWord => (format!(r"\b{}\b", escaped), true),
        SearchMode::MatchCaseWholeWord => (format!(r"\b{}\b", escaped), false),
    };
    RegexBuilder::new(&pattern).case_insensitive(ci).build().ok()
}

pub fn preserve_case(original: &str, replacement: &str) -> String {
    if !original.is_empty() && original.chars().all(|c| c.is_uppercase()) {
        replacement.to_uppercase()
    } else if original.chars().next().map_or(false, |c| c.is_uppercase()) {
        let mut chars = replacement.chars();
        match chars.next() {
            None => String::new(),
            Some(f) => f.to_uppercase().collect::<String>() + &chars.as_str().to_lowercase(),
        }
    } else {
        replacement.to_lowercase()
    }
}

fn replace_text(content: &str, re: &Regex, replacement: &str, mode: ReplaceMode) -> String {
    match mode {
        ReplaceMode::PreserveCase => re
            .replace_all(content, |caps: &regex::Captures| preserve_case(&caps[0], replacement))
            .into_owned(),
        _ => re.replace_all(content, NoExpand(replacement)).into_owned(),
    }
}

pub struct ReplaceSpec<'a> {
    pub search_text: &'a str,
    pub search_mode: SearchMode,
    pub replace_text: &'a str,
    pub replace_mode: ReplaceMode,
}

pub fn replace_file(file: &FileResult, spec: &ReplaceSpec) {
    let content = match std::fs::read_to_string(&file.path) {
        Ok(c) => c,
        Err(_) => return,
    };
    let new_content = match spec.replace_mode {
        ReplaceMode::DeleteLine => {
            let lines: Vec<&str> = content
                .lines()
                .enumerate()
                .filter(|(i, _)| !file.matches.iter().any(|m| m.line_number == i + 1))
                .map(|(_, l)| l)
                .collect();
            lines.join("\n")
        }
        _ => {
            let re = match build_regex(spec.search_text, spec.search_mode) {
                Some(r) => r,
                None => return,
            };
            replace_text(&content, &re, spec.replace_text, spec.replace_mode)
        }
    };
    let _ = std::fs::write(&file.path, new_content);
}

pub fn replace_line(path: &str, line_number: usize, spec: &ReplaceSpec) {
    let content = match std::fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => return,
    };
    let mut lines: Vec<String> = content.lines().map(|l| l.to_string()).collect();
    if line_number == 0 || line_number > lines.len() {
        return;
    }
    let idx = line_number - 1;
    match spec.replace_mode {
        ReplaceMode::DeleteLine => {
            lines.remove(idx);
        }
        _ => {
            let re = match build_regex(spec.search_text, spec.search_mode) {
                Some(r) => r,
                None => return,
            };
            lines[idx] = replace_text(&lines[idx], &re, spec.replace_text, spec.replace_mode);
        }
    }
    let _ = std::fs::write(path, lines.join("\n"));
}
