//! Application state, event handling and rendering.

use std::collections::HashMap;
use std::io::Write;
use std::time::{Duration, Instant};

use crossterm::event::{self, Event, KeyCode, KeyEvent, KeyEventKind, KeyModifiers};
use ratatui_core::layout::{Constraint, Direction, Layout};

use crate::config::Action;
use crate::input::Input;
use crate::replace::{self, preserve_case, ReplaceSpec};
use crate::search::{self, FileResult, ReplaceMode, SearchMode};
use crate::tui::{Buffer, Color, Frame, Modifier, Rect, Style, Terminal};
use crate::widgets::{render_clear, Alignment, Block, Line, List, ListState, Paragraph, Span};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Tab {
    Search,
    Replace,
    List,
    Preview,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum StatusKind {
    Search,
    Replace,
    List,
    Preview,
    Help,
    Confirm,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum DialogKind {
    Modify,
    EmptyReplace,
}

pub struct App {
    root: String,
    keymap: HashMap<KeyEvent, Action>,
    search: Input,
    search_mode: SearchMode,
    replace: Input,
    replace_mode: ReplaceMode,
    results: Vec<FileResult>,
    list_state: ListState,
    preview_file: Option<FileResult>,
    preview_index: Option<usize>,
    preview_state: ListState,
    focus: Option<Tab>,
    tab: Tab,
    status: StatusKind,
    help_visible: bool,
    help_tab: usize,
    dialog: Option<DialogKind>,
    continue_selected: bool,
    should_quit: bool,
    should_suspend: bool,
}

const MODIFY_MSG: &str = "This action will modify the files in this directory.";
const EMPTY_MSG: &str = "Replace text is empty, and replacing with an empty string will remove the matched text.";
const CONFIRM_Q: &str = "Are you sure you want to continue?";

impl App {
    pub fn new(root: String, keymap: HashMap<KeyEvent, Action>) -> Self {
        App {
            root,
            keymap,
            search: Input::default(),
            search_mode: SearchMode::Simple,
            replace: Input::default(),
            replace_mode: ReplaceMode::Simple,
            results: vec![],
            list_state: ListState::default(),
            preview_file: None,
            preview_index: None,
            preview_state: ListState::default(),
            focus: Some(Tab::Search),
            tab: Tab::Search,
            status: StatusKind::Search,
            help_visible: false,
            help_tab: 0,
            dialog: None,
            continue_selected: false,
            should_quit: false,
            should_suspend: false,
        }
    }

    // ------------------------------------------------------------------ main loop

    pub fn run<W: Write>(&mut self, term: &mut Terminal<W>, enter: &dyn Fn() -> std::io::Result<()>, leave: &dyn Fn() -> std::io::Result<()>) -> std::io::Result<()> {
        term.draw(|f| self.render(f))?;
        let mut last_draw = Instant::now();
        loop {
            let timeout = Duration::from_millis(250).saturating_sub(last_draw.elapsed());
            let mut dirty = false;
            if event::poll(timeout)? {
                loop {
                    let ev = event::read()?;
                    match ev {
                        Event::Key(k) => {
                            if k.kind == KeyEventKind::Press {
                                self.handle_key(k);
                            }
                        }
                        Event::Resize(w, h) => {
                            term.resize(Rect::new(0, 0, w, h))?;
                        }
                        _ => {}
                    }
                    dirty = true;
                    if self.should_quit || self.should_suspend {
                        break;
                    }
                    if !event::poll(Duration::from_millis(0))? {
                        break;
                    }
                }
            }
            if self.should_quit {
                break;
            }
            if self.should_suspend {
                self.should_suspend = false;
                leave()?;
                #[cfg(unix)]
                unsafe {
                    libc::raise(libc::SIGTSTP);
                }
                enter()?;
                term.clear()?;
                dirty = true;
            }
            if dirty || last_draw.elapsed() >= Duration::from_millis(250) {
                term.draw(|f| self.render(f))?;
                last_draw = Instant::now();
            }
        }
        Ok(())
    }

    // ------------------------------------------------------------------ keys

    fn handle_key(&mut self, key: KeyEvent) {
        let action = self.keymap.get(&key).cloned();
        // components first
        self.component_key(key);
        if let Some(a) = action {
            self.do_action(a);
        }
    }

    fn component_key(&mut self, key: KeyEvent) {
        if self.help_visible {
            self.help_key(key);
            return;
        }
        if self.dialog.is_some() {
            self.dialog_key(key);
            return;
        }
        match self.focus {
            Some(Tab::Search) => self.search_key(key),
            Some(Tab::Replace) => self.replace_key(key),
            Some(Tab::List) => self.list_key(key),
            Some(Tab::Preview) => self.preview_key(key),
            None => {}
        }
    }

    fn do_action(&mut self, a: Action) {
        match a {
            Action::Quit => self.should_quit = true,
            Action::Suspend => self.should_suspend = true,
            Action::Refresh => {
                if self.help_visible || self.dialog.is_some() {
                    return;
                }
                if !self.search.value().is_empty() {
                    self.do_search();
                }
            }
            Action::LoopOverTabs => {
                if self.help_visible {
                    return;
                }
                if self.dialog.is_some() {
                    return;
                }
                let next = match self.tab {
                    Tab::Search => Tab::Replace,
                    Tab::Replace => Tab::List,
                    Tab::List => Tab::Search,
                    Tab::Preview => Tab::Preview,
                };
                self.set_tab(next);
            }
            Action::BackLoopOverTabs => {
                if self.help_visible || self.dialog.is_some() {
                    return;
                }
                let next = match self.tab {
                    Tab::Search => Tab::List,
                    Tab::Replace => Tab::Search,
                    Tab::List => Tab::Replace,
                    Tab::Preview => Tab::Preview,
                };
                self.set_tab(next);
            }
            Action::ProcessReplace => {
                if self.help_visible || self.dialog.is_some() {
                    return;
                }
                self.process_replace_request();
            }
            Action::ShowHelp => {
                if self.dialog.is_some() {
                    return;
                }
                self.help_visible = true;
                self.status = StatusKind::Help;
            }
            Action::Other => {}
        }
    }

    fn set_tab(&mut self, t: Tab) {
        self.tab = t;
        self.focus = Some(t);
        self.status = match t {
            Tab::Search => StatusKind::Search,
            Tab::Replace => StatusKind::Replace,
            Tab::List => StatusKind::List,
            Tab::Preview => StatusKind::Preview,
        };
    }

    fn help_key(&mut self, key: KeyEvent) {
        if key.modifiers != KeyModifiers::NONE && key.modifiers != KeyModifiers::SHIFT {
            return;
        }
        match key.code {
            KeyCode::Esc | KeyCode::Char('q') => {
                self.help_visible = false;
                let t = self.tab;
                self.set_tab(t);
            }
            KeyCode::Right | KeyCode::Char('l') | KeyCode::Tab => {
                self.help_tab = (self.help_tab + 1) % 2;
            }
            KeyCode::Left | KeyCode::Char('h') => {
                self.help_tab = (self.help_tab + 1) % 2;
            }
            KeyCode::Char('1') => self.help_tab = 0,
            KeyCode::Char('2') => self.help_tab = 1,
            _ => {}
        }
    }

    fn dialog_key(&mut self, key: KeyEvent) {
        match key.code {
            KeyCode::Left | KeyCode::Right | KeyCode::Tab | KeyCode::Char('h') | KeyCode::Char('l') => {
                self.continue_selected = !self.continue_selected;
            }
            KeyCode::Enter => {
                if self.continue_selected {
                    self.dialog = None;
                    self.do_replace_all();
                } else {
                    self.close_dialog();
                }
            }
            KeyCode::Esc => self.close_dialog(),
            _ => {}
        }
    }

    fn close_dialog(&mut self) {
        self.dialog = None;
        self.focus = None;
    }

    fn clear_results(&mut self) {
        self.results.clear();
        self.list_state = ListState::default();
        self.preview_file = None;
        self.preview_index = None;
        self.preview_state = ListState::default();
    }

    fn do_search(&mut self) {
        let text = self.search.value().to_string();
        self.clear_results();
        if text.is_empty() {
            return;
        }
        self.results = search::run_search(&text, self.search_mode, &self.root);
    }

    fn search_key(&mut self, key: KeyEvent) {
        match (key.code, key.modifiers) {
            (KeyCode::Enter, _) => {
                if !self.search.value().is_empty() {
                    self.do_search();
                }
            }
            (KeyCode::Char('n'), KeyModifiers::CONTROL) => {
                self.search_mode = self.search_mode.next();
            }
            _ => {
                if let Some(req) = Input::to_request(&key) {
                    if self.search.handle(req) {
                        self.clear_results();
                    }
                }
            }
        }
    }

    fn replace_key(&mut self, key: KeyEvent) {
        match (key.code, key.modifiers) {
            (KeyCode::Char('n'), KeyModifiers::CONTROL) => {
                self.replace_mode = self.replace_mode.next();
            }
            (KeyCode::Enter, _) => {}
            _ => {
                if self.replace_mode == ReplaceMode::DeleteLine {
                    return;
                }
                if let Some(req) = Input::to_request(&key) {
                    self.replace.handle(req);
                }
            }
        }
    }

    fn select_file(&mut self, idx: Option<usize>) {
        self.list_state.selected = idx;
        self.preview_index = idx;
        self.preview_file = idx.and_then(|i| self.results.get(i).cloned());
        self.preview_state = ListState::default();
    }

    fn list_key(&mut self, key: KeyEvent) {
        if key.modifiers != KeyModifiers::NONE && key.modifiers != KeyModifiers::SHIFT {
            return;
        }
        let len = self.results.len();
        match key.code {
            KeyCode::Char('j') | KeyCode::Down => {
                if len == 0 {
                    return;
                }
                let n = match self.list_state.selected {
                    None => 0,
                    Some(i) => {
                        if i + 1 >= len {
                            0
                        } else {
                            i + 1
                        }
                    }
                };
                self.select_file(Some(n));
            }
            KeyCode::Char('k') | KeyCode::Up => {
                if len == 0 {
                    return;
                }
                let n = match self.list_state.selected {
                    None => len - 1,
                    Some(0) => len - 1,
                    Some(i) => (i - 1).min(len - 1),
                };
                self.select_file(Some(n));
            }
            KeyCode::Char('g') | KeyCode::Char('h') | KeyCode::Left => {
                if len == 0 {
                    return;
                }
                self.select_file(Some(0));
            }
            KeyCode::Char('G') | KeyCode::Char('l') | KeyCode::Right => {
                if len == 0 {
                    return;
                }
                self.select_file(Some(len - 1));
            }
            KeyCode::Enter => {
                self.set_tab(Tab::Preview);
            }
            KeyCode::Char('d') => {
                if let Some(i) = self.list_state.selected {
                    if i < len {
                        self.results.remove(i);
                        let nl = self.results.len();
                        if nl == 0 {
                            self.select_file(None);
                        } else {
                            self.select_file(Some(i.min(nl - 1)));
                        }
                    }
                }
            }
            KeyCode::Char('r') => {
                if let Some(i) = self.list_state.selected {
                    if i < len {
                        let file = self.results.remove(i);
                        let spec = self.spec();
                        replace::replace_file(&file, &spec);
                    }
                }
            }
            _ => {}
        }
    }

    fn spec(&self) -> ReplaceSpec<'_> {
        ReplaceSpec {
            search_text: self.search.value(),
            search_mode: self.search_mode,
            replace_text: self.replace.value(),
            replace_mode: self.replace_mode,
        }
    }

    /// Index of the preview line of each match.
    fn preview_match_lines(&self) -> Vec<usize> {
        let mut v = vec![];
        if let Some(f) = &self.preview_file {
            let mut idx = 0;
            for m in &f.matches {
                v.push(idx + m.before.len());
                idx += m.before.len() + 1 + m.after.len() + 1;
            }
        }
        v
    }

    fn preview_key(&mut self, key: KeyEvent) {
        if key.modifiers != KeyModifiers::NONE && key.modifiers != KeyModifiers::SHIFT {
            return;
        }
        let lines = self.preview_match_lines();
        let sel = self.preview_state.selected;
        match key.code {
            KeyCode::Char('j') | KeyCode::Down => {
                if lines.is_empty() {
                    return;
                }
                let n = match sel {
                    None => lines[0],
                    Some(s) => lines.iter().copied().find(|&l| l > s).unwrap_or(lines[0]),
                };
                self.preview_state.selected = Some(n);
            }
            KeyCode::Char('k') | KeyCode::Up => {
                if lines.is_empty() {
                    return;
                }
                let last = *lines.last().unwrap();
                let n = match sel {
                    None => last,
                    Some(s) => lines.iter().copied().rev().find(|&l| l < s).unwrap_or(last),
                };
                self.preview_state.selected = Some(n);
            }
            KeyCode::Char('g') | KeyCode::Char('h') | KeyCode::Left => {
                if lines.is_empty() {
                    return;
                }
                self.preview_state.selected = Some(lines[0]);
            }
            KeyCode::Char('G') | KeyCode::Char('l') | KeyCode::Right => {
                if lines.is_empty() {
                    return;
                }
                self.preview_state.selected = Some(*lines.last().unwrap());
            }
            KeyCode::Enter | KeyCode::Esc => {
                self.set_tab(Tab::List);
            }
            KeyCode::Char('d') | KeyCode::Char('r') => {
                let s = match sel {
                    Some(s) => s,
                    None => return,
                };
                let mi = match lines.iter().position(|&l| l == s) {
                    Some(mi) => mi,
                    None => return,
                };
                let fi = match self.preview_index {
                    Some(fi) => fi,
                    None => return,
                };
                let path = match &self.preview_file {
                    Some(f) => f.path.clone(),
                    None => return,
                };
                if fi >= self.results.len() || self.results[fi].path != path {
                    return;
                }
                if mi >= self.results[fi].matches.len() {
                    return;
                }
                let m = self.results[fi].matches.remove(mi);
                if key.code == KeyCode::Char('r') {
                    let spec = self.spec();
                    replace::replace_line(&path, m.line_number, &spec);
                }
                if self.results[fi].matches.is_empty() {
                    self.results.remove(fi);
                    let nl = self.results.len();
                    if nl == 0 {
                        self.list_state.selected = None;
                        self.preview_index = None;
                        self.preview_file = None;
                    } else {
                        let ni = fi.min(nl - 1);
                        self.list_state.selected = Some(ni);
                        self.preview_index = Some(ni);
                        self.preview_file = Some(self.results[ni].clone());
                    }
                } else {
                    self.preview_file = Some(self.results[fi].clone());
                }
            }
            _ => {}
        }
    }

    fn process_replace_request(&mut self) {
        if self.results.is_empty() {
            return;
        }
        if self.replace.value().is_empty() {
            self.dialog = Some(DialogKind::EmptyReplace);
        } else if !std::path::Path::new(&self.root).join(".git").exists() {
            self.dialog = Some(DialogKind::Modify);
        } else {
            self.do_replace_all();
            return;
        }
        self.focus = None;
        self.status = StatusKind::Confirm;
    }

    fn do_replace_all(&mut self) {
        {
            let spec = self.spec();
            for f in &self.results {
                replace::replace_file(f, &spec);
            }
        }
        self.search.reset();
        self.replace.reset();
        self.search_mode = SearchMode::Simple;
        self.replace_mode = ReplaceMode::Simple;
        self.clear_results();
        self.set_tab(Tab::Search);
    }

    // ------------------------------------------------------------------ rendering

    fn render(&mut self, f: &mut Frame) {
        let area = f.area;
        let outer = Layout::default()
            .direction(Direction::Vertical)
            .constraints([Constraint::Min(0), Constraint::Length(1)])
            .split(area);
        let main = outer[0];
        let status_area = outer[1];
        let cols = Layout::default()
            .direction(Direction::Horizontal)
            .constraints([Constraint::Percentage(30), Constraint::Percentage(70)])
            .split(main);
        let left = Layout::default()
            .direction(Direction::Vertical)
            .constraints([Constraint::Length(3), Constraint::Length(3), Constraint::Min(0)])
            .split(cols[0]);
        let buf: &mut Buffer = f.buffer;
        let mut cursor = None;
        if let Some(c) = self.render_search(left[0], buf) {
            cursor = Some(c);
        }
        if let Some(c) = self.render_replace(left[1], buf) {
            cursor = Some(c);
        }
        self.render_list(left[2], buf);
        self.render_preview(cols[1], buf);
        self.render_status(status_area, buf);
        if self.help_visible {
            self.render_help(area, buf);
            cursor = None;
        }
        if let Some(d) = self.dialog {
            self.render_dialog(area, buf, d);
            cursor = None;
        }
        f.cursor = cursor;
    }

    fn focused_border(&self, t: Tab) -> Style {
        if self.focus == Some(t) {
            Style::new().fg(Color::Green).add_modifier(Modifier::BOLD)
        } else {
            Style::default()
        }
    }

    fn render_input(&self, area: Rect, buf: &mut Buffer, input: &Input, title: &str, mode: &str, t: Tab, style: Style, placeholder: Option<&str>) -> Option<(u16, u16)> {
        let width = area.width.max(3) - 3;
        let scroll = input.visual_scroll(width as usize);
        let block = Block::bordered()
            .title(Line::raw(title), Alignment::Left)
            .title(Line::raw(format!("[{}]", mode)), Alignment::Right)
            .border_style(self.focused_border(t));
        let text = match placeholder {
            Some(p) => p.to_string(),
            None => input.value().to_string(),
        };
        let p = Paragraph::new(vec![Line::raw(text)]).style(style).scroll_x(scroll as u16).block(block);
        p.render(area, buf);
        if self.focus == Some(t) && placeholder.is_none() && area.width > 0 && area.height > 0 {
            let x = area.x + ((input.visual_cursor().max(scroll) - scroll) as u16) + 1;
            Some((x, area.y + 1))
        } else {
            None
        }
    }

    fn render_search(&self, area: Rect, buf: &mut Buffer) -> Option<(u16, u16)> {
        self.render_input(area, buf, &self.search, "Search", self.search_mode.label(), Tab::Search, Style::new().fg(Color::White), None)
    }

    fn render_replace(&self, area: Rect, buf: &mut Buffer) -> Option<(u16, u16)> {
        if self.replace_mode == ReplaceMode::DeleteLine {
            self.render_input(
                area,
                buf,
                &self.replace,
                "Replace",
                self.replace_mode.label(),
                Tab::Replace,
                Style::new().fg(Color::DarkGray),
                Some("[Entire line will be deleted]"),
            )
        } else {
            self.render_input(area, buf, &self.replace, "Replace", self.replace_mode.label(), Tab::Replace, Style::new().fg(Color::White), None)
        }
    }

    fn render_list(&mut self, area: Rect, buf: &mut Buffer) {
        let items: Vec<Line> = self
            .results
            .iter()
            .map(|r| {
                Line::from_spans(vec![
                    Span::raw(r.display.clone()),
                    Span::raw(" ("),
                    Span::styled(r.total().to_string(), Style::new().fg(Color::Yellow)),
                    Span::raw(")"),
                ])
            })
            .collect();
        let block = Block::bordered().title(Line::raw("Result List"), Alignment::Left).border_style(self.focused_border(Tab::List));
        let list = List::new(items)
            .style(Style::new().fg(Color::White))
            .highlight_style(Style::new().bg(Color::Blue))
            .block(block);
        list.render(area, buf, &mut self.list_state);
    }

    fn render_preview(&mut self, area: Rect, buf: &mut Buffer) {
        let border = if self.focus == Some(Tab::Preview) { Style::new().fg(Color::Green) } else { Style::default() };
        let block = Block::bordered().title(Line::raw("Preview"), Alignment::Left).border_style(border);
        let inner_width = block.inner(area).width as usize;
        let mut items: Vec<Line> = vec![];
        if let Some(file) = &self.preview_file {
            let sel = self.preview_state.selected;
            let rtext = self.replace.value();
            for m in &file.matches {
                let block_start = items.len();
                let n = m.before.len();
                for (i, l) in m.before.iter().enumerate() {
                    let num = m.line_number.saturating_sub(n - i);
                    items.push(Line::from_spans(vec![
                        Span::styled(format!("{:4} ", num), Style::new().fg(Color::Blue)),
                        Span::styled(l.clone(), Style::new().fg(Color::DarkGray)),
                    ]));
                }
                let mut spans = vec![Span::styled(format!("{:4} ", m.line_number), Style::new().fg(Color::LightGreen))];
                if self.replace_mode == ReplaceMode::DeleteLine {
                    spans.push(Span::styled(
                        m.text.clone(),
                        Style::new().fg(Color::White).bg(Color::Red).add_modifier(Modifier::CROSSED_OUT),
                    ));
                } else {
                    let text = &m.text;
                    let mut pos = 0usize;
                    for s in &m.submatches {
                        let start = s.start.min(text.len()).max(pos);
                        let end = s.end.min(text.len()).max(start);
                        if !text.is_char_boundary(start) || !text.is_char_boundary(end) {
                            continue;
                        }
                        if start > pos {
                            spans.push(Span::raw(text[pos..start].to_string()));
                        }
                        let matched = &text[start..end];
                        if rtext.is_empty() {
                            spans.push(Span::styled(matched.to_string(), Style::new().bg(Color::Blue)));
                        } else {
                            spans.push(Span::styled(
                                matched.to_string(),
                                Style::new().fg(Color::White).bg(Color::LightRed).add_modifier(Modifier::CROSSED_OUT),
                            ));
                            let rep = if self.replace_mode == ReplaceMode::PreserveCase {
                                preserve_case(matched, rtext)
                            } else {
                                rtext.to_string()
                            };
                            spans.push(Span::styled(rep, Style::new().fg(Color::White).bg(Color::Green)));
                        }
                        pos = end;
                    }
                    if pos < text.len() {
                        spans.push(Span::raw(text[pos..].to_string()));
                    }
                }
                items.push(Line::from_spans(spans));
                for (i, l) in m.after.iter().enumerate() {
                    items.push(Line::from_spans(vec![
                        Span::styled(format!("{:4} ", m.line_number + i + 1), Style::new().fg(Color::Blue)),
                        Span::styled(l.clone(), Style::new().fg(Color::DarkGray)),
                    ]));
                }
                let sep_color = match sel {
                    Some(s) if block_start <= s => Color::Yellow,
                    _ => Color::DarkGray,
                };
                items.push(Line::styled("-".repeat(inner_width), Style::new().fg(sep_color)));
            }
        }
        let list = List::new(items)
            .highlight_style(Style::new().fg(Color::White).add_modifier(Modifier::BOLD))
            .highlight_symbol("> ")
            .block(block);
        list.render(area, buf, &mut self.preview_state);
    }

    fn status_text(&self) -> &'static str {
        match self.status {
            StatusKind::Search => "Help: <Ctrl-b> | Search: <Enter> | Toggle search mode: <Ctrl-n>",
            StatusKind::Replace => "Help: <Ctrl-b> | Replace: <C-o> | Toggle replace mode: <Ctrl-n>",
            StatusKind::List => "Help: <Ctrl-b> | Open File: <Enter> | Replace File: <r> | Next: <j> | Previous: <k> | Top: <g> | Bottom: <G> | Delete file: <d>",
            StatusKind::Preview => "Help: <Ctrl-b> | Back to list: <Enter> | Replace Line: <r> | Next: <j> | Previous: <k> | Top: <g> | Bottom: <G> | Delete line: <d>",
            StatusKind::Help => "Close Help: <Esc> | Next Tab: <Right> | Previous Tab: <Left>",
            StatusKind::Confirm => "Confirm Replace: <Enter> | Cancel Replace: <Esc>, Left: <h>, Right: <l>, Loop: <Tab>",
        }
    }

    fn render_status(&self, area: Rect, buf: &mut Buffer) {
        let chunks = Layout::default()
            .direction(Direction::Horizontal)
            .constraints([Constraint::Percentage(70), Constraint::Percentage(30)])
            .split(area);
        let p = Paragraph::new(vec![Line::raw(self.status_text())]).style(Style::new().fg(Color::Blue)).wrap(true);
        p.render(chunks[0], buf);
    }

    fn popup_rect(area: Rect, w: u16, h: u16) -> Rect {
        let w = w.min(area.width);
        let h = h.min(area.height);
        Rect { x: area.x + (area.width - w) / 2, y: area.y + (area.height - h) / 2, width: w, height: h }
    }

    fn render_popup_body(&self, popup: Rect, buf: &mut Buffer, lines: Vec<Line>, alignment: Alignment) {
        let fill = Rect {
            x: popup.x + 1,
            y: popup.y + 1,
            width: popup.width.saturating_sub(2),
            height: popup.height.saturating_sub(3),
        };
        buf.set_style(fill.intersection(buf.area), Style::new().fg(Color::White));
        let text_area = Rect {
            x: popup.x + 2,
            y: popup.y + 1,
            width: popup.width.saturating_sub(4),
            height: popup.height.saturating_sub(5),
        };
        let p = Paragraph::new(lines).style(Style::new().fg(Color::White)).alignment(alignment).wrap(true);
        p.render(text_area, buf);
    }

    fn render_help(&self, area: Rect, buf: &mut Buffer) {
        let popup = Self::popup_rect(area, 80, 15);
        render_clear(popup, buf);
        let sel = Style::new().fg(Color::Green);
        let t1 = if self.help_tab == 0 { Line::styled(" [1] Global ", sel) } else { Line::raw(" [1] Global ") };
        let t2 = if self.help_tab == 1 { Line::styled(" [2] Navigation ", sel) } else { Line::raw(" [2] Navigation ") };
        let block = Block::bordered()
            .title(t1, Alignment::Left)
            .title(t2, Alignment::Left)
            .title(Line::raw("Press 'q' to close"), Alignment::Right)
            .border_style(Style::new().fg(Color::Yellow));
        block.render(popup, buf);
        let lines: Vec<&str> = if self.help_tab == 0 {
            vec![
                "",
                "- Ctrl-c: Quit",
                "- Ctrl-d: Quit",
                "- Ctrl-b: Help dialog",
                "- Ctrl-o: Process Replace For All Files",
                "- Ctrl-n: Loop through search and replace modes",
                "- Enter: Select/Deselect file",
                "- d: delete file/delete line from the replace process",
                "- r: Replace Selected File Or Line",
            ]
        } else {
            vec![
                "",
                "- Tab: Loop through panes",
                "- j/UpArrow: Move up",
                "- k/DownArrow: Move down",
                "- h/g/LeftArrow: Move to Top",
                "- l/G/RightArrow: Move to Bottom",
            ]
        };
        self.render_popup_body(popup, buf, lines.into_iter().map(Line::raw).collect(), Alignment::Left);
    }

    fn render_dialog(&self, area: Rect, buf: &mut Buffer, kind: DialogKind) {
        let msg = match kind {
            DialogKind::Modify => MODIFY_MSG,
            DialogKind::EmptyReplace => EMPTY_MSG,
        };
        let maxw = crate::tui::str_width(msg).max(crate::tui::str_width(CONFIRM_Q)) as u16 + 4;
        let popup = Self::popup_rect(area, maxw, 8);
        render_clear(popup, buf);
        let block = Block::bordered()
            .title(Line::raw("Confirm Dialog"), Alignment::Center)
            .border_style(Style::new().fg(Color::Yellow));
        block.render(popup, buf);
        self.render_popup_body(popup, buf, vec![Line::raw(""), Line::raw(msg), Line::raw(CONFIRM_Q)], Alignment::Center);
        // buttons
        if popup.height < 2 {
            return;
        }
        let inner_x = popup.x + 1;
        let inner_w = popup.width.saturating_sub(2);
        let total: u16 = 10 + 8;
        let bx = inner_x + inner_w.saturating_sub(total) / 2;
        let by = popup.y + popup.height - 2;
        let btn_area = Rect { x: bx, y: by, width: total.min(inner_w), height: 2 }.intersection(buf.area);
        let cont = Rect { x: bx, y: by, width: 10, height: 2 }.intersection(btn_area);
        let canc = Rect { x: bx + 10, y: by, width: 8, height: 2 }.intersection(btn_area);
        let sel_style = Style::new().fg(Color::Yellow).add_modifier(Modifier::BOLD);
        let unsel = Style::new().fg(Color::White);
        for (r, label, selected) in [(cont, " Continue ", self.continue_selected), (canc, " Cancel ", !self.continue_selected)] {
            if r.width == 0 || r.height == 0 {
                continue;
            }
            if selected {
                buf.set_style(r, sel_style);
                Line::raw(label).render(Rect { height: 1, ..r }, buf);
            } else {
                Line::styled(label, unsel).render(Rect { height: 1, ..r }, buf);
            }
        }
    }
}
EOF
echo ok"}

