// ------------------------------------------------------------------ generic values

#[derive(Clone, Debug)]
pub enum Value {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Value>),
    Obj(Vec<(String, Value)>),
}

impl Value {
    fn as_string(&self) -> Option<String> {
        match self {
            Value::Str(s) => Some(s.clone()),
            Value::Bool(b) => Some(b.to_string()),
            Value::Num(n) => Some(n.to_string()),
            _ => None,
        }
    }
}

// ------------------------------------------------------------------ JSON5 parser

struct J5<'a> {
    s: &'a [char],
    i: usize,
}

fn pest_error(src: &str, pos: usize, msg: &str) -> String {
    // emulate pest error formatting
    let chars: Vec<char> = src.chars().collect();
    let pos = pos.min(chars.len());
    let mut line = 1;
    let mut col = 1;
    let mut line_start = 0;
    for (i, c) in chars.iter().enumerate().take(pos) {
        if *c == '\n' {
            line += 1;
            col = 1;
            line_start = i + 1;
        } else {
            col += 1;
        }
    }
    let line_end = chars[line_start..].iter().position(|c| *c == '\n').map(|p| line_start + p).unwrap_or(chars.len());
    let line_text: String = chars[line_start..line_end].iter().collect();
    let num = line.to_string();
    let pad = " ".repeat(num.len());
    format!(
        "{pad}--> {line}:{col}\n{pad} |\n{num} | {line_text}\n{pad} | {sp}^---\n{pad} |\n{pad} = {msg}",
        sp = " ".repeat(col - 1)
    )
}

impl<'a> J5<'a> {
    fn peek(&self) -> Option<char> {
        self.s.get(self.i).copied()
    }
    fn skip_ws(&mut self) {
        loop {
            match self.peek() {
                Some(c) if c.is_whitespace() || c == '\u{feff}' => self.i += 1,
                Some('/') => {
                    if self.s.get(self.i + 1) == Some(&'/') {
                        while let Some(c) = self.peek() {
                            if c == '\n' {
                                break;
                            }
                            self.i += 1;
                        }
                    } else if self.s.get(self.i + 1) == Some(&'*') {
                        self.i += 2;
                        while self.i < self.s.len() && !(self.peek() == Some('*') && self.s.get(self.i + 1) == Some(&'/')) {
                            self.i += 1;
                        }
                        self.i = (self.i + 2).min(self.s.len());
                    } else {
                        return;
                    }
                }
                _ => return,
            }
        }
    }
    fn err(&self, msg: &str) -> (usize, String) {
        (self.i, msg.to_string())
    }
    fn value(&mut self) -> Result<Value, (usize, String)> {
        self.skip_ws();
        match self.peek() {
            Some('{') => self.object(),
            Some('[') => self.array(),
            Some('"') | Some('\'') => Ok(Value::Str(self.string()?)),
            Some(c) if c == '-' || c == '+' || c == '.' || c.is_ascii_digit() => self.number(),
            Some(_) => {
                let start = self.i;
                let id = self.ident();
                match id.as_str() {
                    "true" => Ok(Value::Bool(true)),
                    "false" => Ok(Value::Bool(false)),
                    "null" => Ok(Value::Null),
                    "Infinity" => Ok(Value::Num(f64::INFINITY)),
                    "NaN" => Ok(Value::Num(f64::NAN)),
                    _ => {
                        self.i = start;
                        Err(self.err("expected value"))
                    }
                }
            }
            None => Err(self.err("expected value")),
        }
    }
    fn ident(&mut self) -> String {
        let mut s = String::new();
        while let Some(c) = self.peek() {
            if c.is_alphanumeric() || c == '_' || c == '$' {
                s.push(c);
                self.i += 1;
            } else {
                break;
            }
        }
        s
    }
    fn number(&mut self) -> Result<Value, (usize, String)> {
        let start = self.i;
        let mut s = String::new();
        while let Some(c) = self.peek() {
            if c.is_ascii_alphanumeric() || c == '.' || c == '-' || c == '+' {
                s.push(c);
                self.i += 1;
            } else {
                break;
            }
        }
        match s.parse::<f64>() {
            Ok(n) => Ok(Value::Num(n)),
            Err(_) => {
                if let Some(h) = s.strip_prefix("0x").or_else(|| s.strip_prefix("0X")) {
                    if let Ok(n) = i64::from_str_radix(h, 16) {
                        return Ok(Value::Num(n as f64));
                    }
                }
                self.i = start;
                Err(self.err("expected value"))
            }
        }
    }
    fn string(&mut self) -> Result<String, (usize, String)> {
        let q = self.peek().unwrap();
        self.i += 1;
        let mut s = String::new();
        loop {
            match self.peek() {
                None => return Err(self.err("expected char_literal")),
                Some(c) if c == q => {
                    self.i += 1;
                    return Ok(s);
                }
                Some('\\') => {
                    self.i += 1;
                    match self.peek() {
                        Some('n') => s.push('\n'),
                        Some('t') => s.push('\t'),
                        Some('r') => s.push('\r'),
                        Some('b') => s.push('\u{8}'),
                        Some('f') => s.push('\u{c}'),
                        Some('v') => s.push('\u{b}'),
                        Some('0') => s.push('\0'),
                        Some('\n') => {}
                        Some('u') => {
                            let hex: String = self.s[self.i + 1..(self.i + 5).min(self.s.len())].iter().collect();
                            if let Ok(n) = u32::from_str_radix(&hex, 16) {
                                if let Some(c) = char::from_u32(n) {
                                    s.push(c);
                                }
                            }
                            self.i += 4;
                        }
                        Some(c) => s.push(c),
                        None => return Err(self.err("expected char_literal")),
                    }
                    self.i += 1;
                }
                Some(c) => {
                    s.push(c);
                    self.i += 1;
                }
            }
        }
    }
    fn object(&mut self) -> Result<Value, (usize, String)> {
        self.i += 1;
        let mut out = vec![];
        loop {
            self.skip_ws();
            match self.peek() {
                Some('}') => {
                    self.i += 1;
                    return Ok(Value::Obj(out));
                }
                Some('"') | Some('\'') => {
                    let k = self.string()?;
                    self.skip_ws();
                    if self.peek() != Some(':') {
                        return Err(self.err("expected `:`"));
                    }
                    self.i += 1;
                    let v = self.value()?;
                    out.push((k, v));
                }
                Some(c) if c.is_alphabetic() || c == '_' || c == '$' => {
                    let k = self.ident();
                    self.skip_ws();
                    if self.peek() != Some(':') {
                        return Err(self.err("expected `:`"));
                    }
                    self.i += 1;
                    let v = self.value()?;
                    out.push((k, v));
                }
                _ => return Err(self.err("expected identifier or string")),
            }
            self.skip_ws();
            match self.peek() {
                Some(',') => {
                    self.i += 1;
                }
                Some('}') => {
                    self.i += 1;
                    return Ok(Value::Obj(out));
                }
                _ => return Err(self.err("expected `,` or `}`")),
            }
        }
    }
    fn array(&mut self) -> Result<Value, (usize, String)> {
        self.i += 1;
        let mut out = vec![];
        loop {
            self.skip_ws();
            if self.peek() == Some(']') {
                self.i += 1;
                return Ok(Value::Arr(out));
            }
            out.push(self.value()?);
            self.skip_ws();
            match self.peek() {
                Some(',') => self.i += 1,
                Some(']') => {
                    self.i += 1;
                    return Ok(Value::Arr(out));
                }
                _ => return Err(self.err("expected `,` or `]`")),
            }
        }
    }
}

fn parse_json5(src: &str) -> Result<Value, String> {
    let chars: Vec<char> = src.chars().collect();
    let mut p = J5 { s: &chars, i: 0 };
    let r = p.value();
    match r {
        Ok(v) => {
            p.skip_ws();
            if p.i < chars.len() {
                return Err(pest_error(src, p.i, "expected EOI"));
            }
            Ok(v)
        }
        Err((pos, msg)) => Err(pest_error(src, pos, &msg)),
    }
}

// ------------------------------------------------------------------ TOML / YAML / INI (minimal)

fn unquote(s: &str) -> String {
    let s = s.trim();
    if (s.starts_with('"') && s.ends_with('"') && s.len() >= 2) || (s.starts_with('\'') && s.ends_with('\'') && s.len() >= 2) {
        s[1..s.len() - 1].to_string()
    } else {
        s.to_string()
    }
}

fn split_kv(line: &str, sep: char) -> Option<(String, String)> {
    // handle quoted keys containing the separator
    let line = line.trim();
    if line.starts_with('"') || line.starts_with('\'') {
        let q = line.chars().next().unwrap();
        let end = line[1..].find(q)? + 1;
        let key = line[1..end].to_string();
        let rest = line[end + 1..].trim_start();
        let rest = rest.strip_prefix(sep)?;
        return Some((key, unquote(strip_comment(rest))));
    }
    let pos = line.find(sep)?;
    Some((line[..pos].trim().to_string(), unquote(strip_comment(&line[pos + 1..]))))
}

fn strip_comment(s: &str) -> &str {
    let t = s.trim();
    if t.starts_with('"') || t.starts_with('\'') {
        let q = t.chars().next().unwrap();
        if let Some(end) = t[1..].find(q) {
            return &t[..end + 2];
        }
        return t;
    }
    match t.find(" #") {
        Some(p) => t[..p].trim(),
        None => t,
    }
}

fn parse_sectioned(src: &str, sep: char) -> Value {
    let mut root: Vec<(String, Value)> = vec![];
    let mut section: Option<String> = None;
    for line in src.lines() {
        let l = line.trim();
        if l.is_empty() || l.starts_with('#') || l.starts_with(';') {
            continue;
        }
        if l.starts_with('[') && l.ends_with(']') {
            section = Some(unquote(&l[1..l.len() - 1]));
            continue;
        }
        if let Some((k, v)) = split_kv(l, sep) {
            match &section {
                None => root.push((k, Value::Str(v))),
                Some(sec) => {
                    if let Some((_, Value::Obj(o))) = root.iter_mut().find(|(n, _)| n == sec) {
                        o.push((k, Value::Str(v)));
                    } else {
                        root.push((sec.clone(), Value::Obj(vec![(k, Value::Str(v))])));
                    }
                }
            }
        }
    }
    Value::Obj(root)
}

fn parse_yaml(src: &str) -> Value {
    let mut root: Vec<(String, Value)> = vec![];
    let mut section: Option<(usize, String)> = None;
    for line in src.lines() {
        if line.trim().is_empty() || line.trim_start().starts_with('#') || line.trim() == "---" {
            continue;
        }
        let indent = line.len() - line.trim_start().len();
        let l = line.trim();
        if let Some((k, v)) = split_kv(l, ':') {
            if v.is_empty() {
                section = Some((indent, k.clone()));
                root.push((k, Value::Obj(vec![])));
                continue;
            }
            match &section {
                Some((si, sec)) if indent > *si => {
                    if let Some((_, Value::Obj(o))) = root.iter_mut().find(|(n, _)| n == sec) {
                        o.push((k, Value::Str(v)));
                    }
                }
                _ => {
                    section = None;
                    root.push((k, Value::Str(v)));
                }
            }
        }
    }
    Value::Obj(root)
}

fn diff_paths(path: &Path, base: &Path) -> PathBuf {
    use std::path::Component;
    let pc: Vec<Component> = path.components().collect();
    let bc: Vec<Component> = base.components().collect();
    let mut i = 0;
    while i < pc.len() && i < bc.len() && pc[i] == bc[i] {
        i += 1;
    }
    let mut out = PathBuf::new();
    for _ in i..bc.len() {
        out.push("..");
    }
    for c in &pc[i..] {
        out.push(c.as_os_str());
    }
    out
}

fn display_uri(path: &Path) -> String {
    match std::env::current_dir() {
        Ok(cwd) if path.is_absolute() => diff_paths(path, &cwd).to_string_lossy().into_owned(),
        _ => path.to_string_lossy().into_owned(),
    }
}

pub fn load_keymap() -> Result<HashMap<KeyEvent, crate::config::Action>, String> {
    let dir = get_config_dir();
    let files: [(&str, &str); 5] = [
        ("config.json5", "json5"),
        ("config.json", "json"),
        ("config.yaml", "yaml"),
        ("config.toml", "toml"),
        ("config.ini", "ini"),
    ];
    // merged user bindings (later files override earlier)
    let mut user: Vec<(String, Value)> = vec![];
    for (name, fmt) in files.iter() {
        let p = dir.join(name);
        if !p.is_file() {
            continue;
        }
        let src = match std::fs::read_to_string(&p) {
            Ok(s) => s,
            Err(e) => return Err(format!("{} in {}", e, display_uri(&p))),
        };
        let v = match *fmt {
            "json5" | "json" => parse_json5(&src).map_err(|e| format!("{} in {}", e, display_uri(&p)))?,
            "yaml" => parse_yaml(&src),
            "toml" => parse_sectioned(&src, '='),
            _ => parse_sectioned(&src, '='),
        };
        if let Value::Obj(top) = v {
            for (k, v) in top {
                if k.to_lowercase() == "keybindings" {
                    if let Value::Obj(kb) = v {
                        for (key, val) in kb {
                            if let Some(pos) = user.iter().position(|(k2, _)| *k2 == key) {
                                user[pos] = (key, val);
                            } else {
                                user.push((key, val));
                            }
                        }
                    }
                }
            }
        }
    }
    let mut map: HashMap<KeyEvent, Action> = HashMap::new();
    for (key, val) in user {
        let name = match val.as_string() {
            Some(s) => s,
            None => return Err("invalid type: expected a string".to_string()),
        };
        let action = parse_action(&name)?;
        let seq = parse_key_sequence(&key).map_err(|e| e.to_string())?;
        if seq.len() == 1 {
            map.insert(seq[0], action);
        }
    }
    for (k, a) in DEFAULT_BINDINGS {
        let seq = parse_key_sequence(k).unwrap();
        let action = parse_action(a).unwrap();
        map.entry(seq[0]).or_insert(action);
    }
    Ok(map)
}
