use std::io::{self, BufWriter, Write};

use clap::{Arg, Command};
use crossterm::{
    cursor,
    execute,
    terminal::{self, EnterAlternateScreen, LeaveAlternateScreen},
};

const VERSION_MESSAGE: &str = "0.3.4- (2026-06-11)";

fn version() -> String {
    format!(
        "{}\n\nAuthors: Yassine Bridi <ybridi@gmail.com>\n\nConfig directory: {}",
        VERSION_MESSAGE,
        config::get_config_dir().display()
    )
}

fn enter_tui() -> io::Result<()> {
    terminal::enable_raw_mode()?;
    execute!(io::stderr(), EnterAlternateScreen, cursor::Hide)?;
    Ok(())
}

fn leave_tui() -> io::Result<()> {
    if terminal::is_raw_mode_enabled()? {
        execute!(io::stderr(), LeaveAlternateScreen, cursor::Show)?;
        terminal::disable_raw_mode()?;
    }
    Ok(())
}

fn report_error(msg: &str) -> ! {
    let mut err = io::stderr();
    let _ = writeln!(err, "serpl error: Something went wrong");
    let indented = msg.replace('\n', "\n      ");
    let _ = writeln!(err, "Error: \n   0: \x1b[91m{}\x1b[0m", indented);
    std::process::exit(1);
}

fn main() {
    let matches = Command::new("serpl")
        .version(version())
        .author("Yassine Bridi <ybridi@gmail.com>")
        .about("A simple terminal UI for search and replace, ala VS Code")
        .arg(
            Arg::new("project_root")
                .short('p')
                .long("project-root")
                .value_name("PATH")
                .help("Path to the project root")
                .default_value("."),
        )
        .get_matches();
    let root = matches.get_one::<String>("project_root").cloned().unwrap_or_else(|| ".".to_string());

    let keymap = match config::load_keymap() {
        Ok(k) => k,
        Err(e) => report_error(&e),
    };

    let default_hook = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |info| {
        let _ = leave_tui();
        default_hook(info);
    }));

    if let Err(e) = enter_tui() {
        report_error(&e.to_string());
    }
    let writer = BufWriter::with_capacity(1 << 16, io::stderr());
    let result = (|| -> io::Result<()> {
        let mut term = tui::Terminal::new(writer)?;
        let mut app = app::App::new(root, keymap);
        app.run(&mut term, &enter_tui, &leave_tui)?;
        term.writer().flush()?;
        Ok(())
    })();
    let _ = leave_tui();
    if let Err(e) = result {
        report_error(&e.to_string());
    }
}
