            }
            let mut q = self.skip(p);
            if let Some(c) = self.lit(q, ",") {
                q = self.skip(c);
            }
            let e = self.lit(q, "}")?;
            Some((Value::Obj(out), e))
        })();
        if r.is_none() {
            self.fail("object", pos);
        }
        r
    }
    fn array(&mut self, pos: usize) -> Option<(Value, usize)> {
        let r = (|| {
            let p = self.lit(pos, "[")?;
            let p1 = self.skip(p);
            if let Some(e) = self.lit(p1, "]") {
                return Some((Value::Arr(vec![]), e));
            }
            let (first, mut p) = self.value(p1)?;
