                q = self.skip(c);
            }
            let e = self.lit(q, "]")?;
            Some((Value::Arr(out), e))
        })();
        if r.is_none() {
            self.fail("array", pos);
        }
        r
    }
}

fn pest_error(src: &str, pos: usize, attempts: &[&str]) -> String {
    let chars: Vec<char> = src.chars().collect();
    let pos = pos.min(chars.len());
    let mut line = 1;
    let mut col = 1;
    let mut line_start = 0;
    for (i, c) in chars.iter().enumerate().take(pos) {
        if *c == '\n' {
            line += 1;
            col = 1;
            line_start = i + 1;
        } else {
            col += 1;
        }
    }
    let line_end = chars[line_start..]
        .iter()
        .position(|c| *c == '\n' || *c == '\r')
        .map(|p| line_start + p)
        .unwrap_or(chars.len());
    let line_text: String = chars[line_start..line_end].iter().collect();
