    rules.sort();
    rules.dedup();
    let msg = match rules.len() {
        0 => "unknown parsing error".to_string(),
        1 => format!("expected {}", rules[0]),
        2 => format!("expected {} or {}", rules[0], rules[1]),
        n => format!("expected {}, or {}", rules[..n - 1].join(", "), rules[n - 1]),
    };
