        "{pad}--> {line}:{col}\n{pad} |\n{num} | {line_text}\n{pad} | {sp}^---\n{pad} |\n{pad} = {msg}",
        sp = " ".repeat(col - 1)
    )
}

fn parse_json5(src: &str) -> Result<Value, String> {
    let mut p = J5 { s: src.chars().collect(), furthest: 0, attempts: vec![] };
