new=r'''// ------------------------------------------------------------------ JSON5 parser
// A small PEG parser following the json5 grammar, reporting errors like pest does.

struct J5 {
    s: Vec<char>,
    furthest: usize,
    attempts: Vec<&'static str>,
}

fn is_ws_char(c: char) -> bool {
    matches!(c, '\t' | '\u{000B}' | '\u{000C}' | ' ' | '\u{00A0}' | '\u{FEFF}' | '\n' | '\r' | '\u{2028}' | '\u{2029}')
        || (c.is_whitespace() && !c.is_control())
}

impl J5 {
    fn fail(&mut self, rule: &'static str, pos: usize) {
        if pos > self.furthest {
            self.furthest = pos;
            self.attempts.clear();
            self.attempts.push(rule);
        } else if pos == self.furthest && !self.attempts.contains(&rule) {
            self.attempts.push(rule);
        }
    }
    fn at(&self, pos: usize) -> Option<char> {
        self.s.get(pos).copied()
    }
    fn lit(&self, pos: usize, l: &str) -> Option<usize> {
        let mut p = pos;
        for c in l.chars() {
            if self.at(p) != Some(c) {
                return None;
            }
            p += 1;
        }
        Some(p)
    }
    fn skip(&self, mut pos: usize) -> usize {
        loop {
            match self.at(pos) {
                Some(c) if is_ws_char(c) => pos += 1,
                Some('/') if self.at(pos + 1) == Some('*') => {
                    let mut p = pos + 2;
                    loop {
                        if p >= self.s.len() {
                            return pos;
                        }
                        if self.at(p) == Some('*') && self.at(p + 1) == Some('/') {
                            p += 2;
                            break;
                        }
                        p += 1;
                    }
                    pos = p;
                }
                Some('/') if self.at(pos + 1) == Some('/') => {
                    let mut p = pos + 2;
                    while let Some(c) = self.at(p) {
                        if c == '\n' || c == '\r' || c == '\u{2028}' || c == '\u{2029}' {
                            break;
                        }
                        p += 1;
                    }
                    pos = p;
                }
                _ => return pos,
            }
        }
    }
    fn value(&mut self, pos: usize) -> Option<(Value, usize)> {
        if let Some(p) = self.lit(pos, "null") {
            return Some((Value::Null, p));
        }
        self.fail("null", pos);
        if let Some(p) = self.lit(pos, "true") {
            return Some((Value::Bool(true), p));
        }
        if let Some(p) = self.lit(pos, "false") {
            return Some((Value::Bool(false), p));
        }
        self.fail("boolean", pos);
        if let Some((st, p)) = self.string(pos) {
            return Some((Value::Str(st), p));
        }
        if let Some((n, p)) = self.number(pos) {
            return Some((Value::Num(n), p));
        }
        self.fail("number", pos);
        if let Some(r) = self.object(pos) {
            return Some(r);
        }
        if let Some(r) = self.array(pos) {
            return Some(r);
        }
        None
    }
    fn string(&mut self, pos: usize) -> Option<(String, usize)> {
        let q = match self.at(pos) {
            Some(c) if c == '"' || c == '\'' => c,
            _ => {
                self.fail("string", pos);
                return None;
            }
        };
        let mut p = pos + 1;
        let mut out = String::new();
        loop {
            match self.at(p) {
                None | Some('\n') | Some('\r') => {
                    self.fail("string", pos);
                    return None;
                }
                Some(c) if c == q => return Some((out, p + 1)),
                Some('\\') => {
                    p += 1;
                    match self.at(p) {
                        Some('n') => out.push('\n'),
                        Some('t') => out.push('\t'),
                        Some('r') => out.push('\r'),
                        Some('b') => out.push('\u{8}'),
                        Some('f') => out.push('\u{c}'),
                        Some('v') => out.push('\u{b}'),
                        Some('0') => out.push('\0'),
                        Some('\n') => {}
                        Some('u') => {
                            let hex: String = (1..5).filter_map(|i| self.at(p + i)).collect();
                            if let Some(c) = u32::from_str_radix(&hex, 16).ok().and_then(char::from_u32) {
                                out.push(c);
                            }
                            p += 4;
                        }
                        Some('x') => {
                            let hex: String = (1..3).filter_map(|i| self.at(p + i)).collect();
                            if let Some(c) = u32::from_str_radix(&hex, 16).ok().and_then(char::from_u32) {
                                out.push(c);
                            }
                            p += 2;
                        }
                        Some(c) => out.push(c),
                        None => {
                            self.fail("string", pos);
                            return None;
                        }
                    }
                    p += 1;
                }
                Some(c) => {
                    out.push(c);
                    p += 1;
                }
            }
        }
    }
    fn number(&mut self, pos: usize) -> Option<(f64, usize)> {
        let mut p = pos;
        let mut neg = false;
        if let Some(c) = self.at(p) {
            if c == '+' || c == '-' {
                neg = c == '-';
                p += 1;
            }
        }
        for (word, val) in [("Infinity", f64::INFINITY), ("NaN", f64::NAN)] {
            if let Some(e) = self.lit(p, word) {
                return Some((if neg { -val } else { val }, e));
            }
        }
        if self.lit(p, "0x").is_some() || self.lit(p, "0X").is_some() {
            let mut e = p + 2;
            while self.at(e).map_or(false, |c| c.is_ascii_hexdigit()) {
                e += 1;
            }
            if e == p + 2 {
                return None;
            }
            let h: String = self.s[p + 2..e].iter().collect();
            let v = i64::from_str_radix(&h, 16).unwrap_or(0) as f64;
            return Some((if neg { -v } else { v }, e));
        }
        let start = p;
        let mut digits = 0;
        while self.at(p).map_or(false, |c| c.is_ascii_digit()) {
            p += 1;
            digits += 1;
        }
        if self.at(p) == Some('.') {
            p += 1;
            while self.at(p).map_or(false, |c| c.is_ascii_digit()) {
                p += 1;
                digits += 1;
            }
        }
        if digits == 0 {
            return None;
        }
        if matches!(self.at(p), Some('e') | Some('E')) {
            let mut e = p + 1;
            if matches!(self.at(e), Some('+') | Some('-')) {
                e += 1;
            }
            let ds = e;
            while self.at(e).map_or(false, |c| c.is_ascii_digit()) {
                e += 1;
            }
            if e > ds {
                p = e;
            }
        }
        let txt: String = self.s[start..p].iter().collect();
        let v: f64 = txt.parse().unwrap_or(0.0);
        Some((if neg { -v } else { v }, p))
    }
    fn identifier(&mut self, pos: usize) -> Option<(String, usize)> {
        let mut p = pos;
        let mut out = String::new();
        match self.at(p) {
            Some(c) if c.is_alphabetic() || c == '$' || c == '_' => {
                out.push(c);
                p += 1;
            }
            _ => {
                self.fail("identifier", pos);
                return None;
            }
        }
        while let Some(c) = self.at(p) {
            if c.is_alphanumeric() || c == '$' || c == '_' || c == '\u{200C}' || c == '\u{200D}' {
                out.push(c);
                p += 1;
            } else {
                break;
            }
        }
        Some((out, p))
    }
    fn key(&mut self, pos: usize) -> Option<(String, usize)> {
        if let Some(r) = self.identifier(pos) {
            return Some(r);
        }
        self.string(pos)
    }
    fn pair(&mut self, pos: usize) -> Option<((String, Value), usize)> {
        let (k, p) = self.key(pos)?;
        let p = self.skip(p);
        let p = self.lit(p, ":")?;
        let p = self.skip(p);
        let (v, p) = self.value(p)?;
        Some(((k, v), p))
    }
    fn object(&mut self, pos: usize) -> Option<(Value, usize)> {
        let r = (|| {
            let p = self.lit(pos, "{")?;
            let p1 = self.skip(p);
            if let Some(e) = self.lit(p1, "}") {
                return Some((Value::Obj(vec![]), e));
            }
            let (first, mut p) = self.pair(p1)?;
            let mut out = vec![first];
            loop {
                let q = self.skip(p);
                let q = match self.lit(q, ",") {
                    Some(q) => q,
                    None => break,
                };
                let q = self.skip(q);
                match self.pair(q) {
                    Some((kv, e)) => {
                        out.push(kv);
                        p = e;
                    }
                    None => break,
                }
            }
            let mut q = self.skip(p);
            if let Some(c) = self.lit(q, ",") {
                q = self.skip(c);
            }
            let e = self.lit(q, "}")?;
            Some((Value::Obj(out), e))
        })();
        if r.is_none() {
            self.fail("object", pos);
        }
        r
    }
    fn array(&mut self, pos: usize) -> Option<(Value, usize)> {
        let r = (|| {
            let p = self.lit(pos, "[")?;
            let p1 = self.skip(p);
            if let Some(e) = self.lit(p1, "]") {
                return Some((Value::Arr(vec![]), e));
            }
            let (first, mut p) = self.value(p1)?;
            let mut out = vec![first];
            loop {
                let q = self.skip(p);
                let q = match self.lit(q, ",") {
                    Some(q) => q,
                    None => break,
                };
                let q = self.skip(q);
                match self.value(q) {
                    Some((v, e)) => {
                        out.push(v);
                        p = e;
                    }
                    None => break,
                }
            }
            let mut q = self.skip(p);
            if let Some(c) = self.lit(q, ",") {
                q = self.skip(c);
            }
            let e = self.lit(q, "]")?;
            Some((Value::Arr(out), e))
        })();
        if r.is_none() {
            self.fail("array", pos);
        }
        r
    }
}

fn pest_error(src: &str, pos: usize, attempts: &[&str]) -> String {
    let chars: Vec<char> = src.chars().collect();
    let pos = pos.min(chars.len());
    let mut line = 1;
    let mut col = 1;
    let mut line_start = 0;
    for (i, c) in chars.iter().enumerate().take(pos) {
        if *c == '\n' {
            line += 1;
            col = 1;
            line_start = i + 1;
        } else {
            col += 1;
        }
    }
    let line_end = chars[line_start..]
        .iter()
        .position(|c| *c == '\n' || *c == '\r')
        .map(|p| line_start + p)
        .unwrap_or(chars.len());
    let line_text: String = chars[line_start..line_end].iter().collect();
    let num = line.to_string();
    let pad = " ".repeat(num.len());
    let mut rules: Vec<&str> = attempts.to_vec();
    rules.sort();
    rules.dedup();
    let msg = match rules.len() {
        0 => "unknown parsing error".to_string(),
        1 => format!("expected {}", rules[0]),
        2 => format!("expected {} or {}", rules[0], rules[1]),
        n => format!("expected {}, or {}", rules[..n - 1].join(", "), rules[n - 1]),
    };
    format!(
        "{pad}--> {line}:{col}\n{pad} |\n{num} | {line_text}\n{pad} | {sp}^---\n{pad} |\n{pad} = {msg}",
        sp = " ".repeat(col - 1)
    )
}

fn parse_json5(src: &str) -> Result<Value, String> {
    let mut p = J5 { s: src.chars().collect(), furthest: 0, attempts: vec![] };
    let start = p.skip(0);
    match p.value(start) {
        Some((v, e)) => {
            let e = p.skip(e);
            if e < p.s.len() {
                p.fail("EOI", e);
                let (f, a) = (p.furthest, p.attempts.clone());
                return Err(pest_error(src, f, &a));
            }
            Ok(v)
        }
        None => {
            let (f, a) = (p.furthest, p.attempts.clone());
            Err(pest_error(src, f, &a))
        }
    }
}

