{"command":"cd /workspace && python3 - <<'EOF'
p='src/config.rs'; s=open(p).read()
s=s.replace("""fn parse_yaml(src: &str) -> Value {""",r'''/// Minimal TOML validation producing toml_edit like diagnostics.
fn toml_check(src: &str) -> Result<(), (usize, usize, &'static str)> {
    fn bare(c: char) -> bool {
        c.is_ascii_alphanumeric() || c == '_' || c == '-'
    }
    for (li, line) in src.lines().enumerate() {
        let chars: Vec<char> = line.chars().collect();
        let mut i = 0;
        while i < chars.len() && (chars[i] == ' ' || chars[i] == '\t') {
            i += 1;
        }
        if i >= chars.len() || chars[i] == '#' {
            continue;
        }
        // parse a (dotted) key starting at i, returns end index
        let parse_key = |mut i: usize| -> Option<usize> {
            loop {
                while i < chars.len() && (chars[i] == ' ' || chars[i] == '\t') {
                    i += 1;
                }
                if i < chars.len() && (chars[i] == '"' || chars[i] == '\'') {
                    let q = chars[i];
                    i += 1;
                    while i < chars.len() && chars[i] != q {
                        if chars[i] == '\\' && q == '"' {
                            i += 1;
                        }
                        i += 1;
                    }
                    if i >= chars.len() {
                        return None;
                    }
                    i += 1;
                } else {
                    let st = i;
                    while i < chars.len() && bare(chars[i]) {
                        i += 1;
                    }
                    if i == st {
                        return None;
                    }
                }
                let mut j = i;
                while j < chars.len() && (chars[j] == ' ' || chars[j] == '\t') {
                    j += 1;
                }
                if j < chars.len() && chars[j] == '.' {
                    i = j + 1;
                    continue;
                }
                return Some(i);
            }
        };
        if chars[i] == '[' {
            let start = if chars.get(i + 1) == Some(&'[') { i + 2 } else { i + 1 };
            let end = match parse_key(start) {
                Some(e) => e,
                None => return Err((li + 1, start + 1, "invalid table header\nexpected `.`, `]`")),
            };
            let mut j = end;
            while j < chars.len() && (chars[j] == ' ' || chars[j] == '\t') {
                j += 1;
            }
            if j >= chars.len() || chars[j] != ']' {
                return Err((li + 1, end + 1, "invalid table header\nexpected `.`, `]`"));
            }
            continue;
        }
        let end = match parse_key(i) {
            Some(e) => e,
            None => return Err((li + 1, i + 1, "invalid key")),
        };
        let mut j = end;
        while j < chars.len() && (chars[j] == ' ' || chars[j] == '\t') {
            j += 1;
        }
        if j >= chars.len() || chars[j] != '=' {
            return Err((li + 1, end + 1, "expected `.`, `=`"));
        }
        j += 1;
        while j < chars.len() && (chars[j] == ' ' || chars[j] == '\t') {
            j += 1;
        }
        let rest: String = chars[j..].iter().collect();
        let ok = rest.starts_with('"')
            || rest.starts_with('\'')
            || rest.starts_with('[')
            || rest.starts_with('{')
            || rest.starts_with("true")
            || rest.starts_with("false")
            || rest.chars().next().map_or(false, |c| c.is_ascii_digit() || c == '+' || c == '-');
        if !ok {
            return Err((li + 1, j + 1, "invalid string\nexpected `\"`, `'`"));
        }
    }
    Ok(())
}

fn toml_error(src: &str, line: usize, col: usize, msg: &str, uri: &str) -> String {
    let text = src.lines().nth(line - 1).unwrap_or("");
    let num = line.to_string();
    let pad = " ".repeat(num.len());
    let msg = msg.replace('\n', "\n      ");
    format!(
        "\u{0}TOML parse error at line {line}, column {col}\n   0: {pad} |\n   0: {num} | {text}\n   0: {pad} | {sp}^\n   0: {msg}\n   0:  in {uri}",
        sp = " ".repeat(col.saturating_sub(1))
    )
}

fn parse_yaml(src: &str) -> Value {''')
s=s.replace("""            "toml" => parse_sectioned(&src, '='),""","""            "toml" => {
                if let Err((l, c, m)) = toml_check(&src) {
                    return Err(toml_error(&src, l, c, m, &display_uri(&p)));
                }
                parse_sectioned(&src, '=')
            }""")
open(p,'w').write(s)
p='src/main.rs'; s=open(p).read()
s=s.replace("""    let indented = msg.replace('\\n', "\\n      ");
    let _ = writeln!(err, "Error: \\n   0: \\x1b[91m{}\\x1b[0m", indented);""","""    let body = match msg.strip_prefix('\\u{0}') {
        Some(raw) => raw.to_string(),
        None => msg.replace('\\n', "\\n      "),
    };
    let _ = writeln!(err, "Error: \\n   0: \\x1b[91m{}\\x1b[0m", body);""")
open(p,'w').write(s)
